async function checkAuth() {
    if (!AUTH_TOKEN) {
        window.location.href = '/login.html';
        return false;
    }
    try {
        const res = await fetch('/api/auth/me', { headers: { 'Authorization': `Bearer ${AUTH_TOKEN}` } });
        if (!res.ok) {
            localStorage.removeItem('gp_token');
            window.location.href = '/login.html';
            return false;
        }
        return true;
    } catch (e) {
        return false;
    }
}

function authHeaders() {
