        }
        loadPlayersChart();
        updateNotifBadge();
    } catch(e) {
        console.error(e);
    }
};

window.loadServerHistory = async () => {
    const id = document.getElementById('historyServerSelect')?.value;
    if (!id) return;
    try {
        const res = await fetch(`/api/history/${id}`);
