using Avalonia.Controls;
using Avalonia.Controls.ApplicationLifetimes;
using Avalonia.Controls.Templates;
using Avalonia.Input.Platform;
using Avalonia.Markup.Xaml;
using Avalonia.Platform.Storage;
using DinoEditor.App.Docks;
using DinoEditor.App.Flight;
using DinoEditor.App.Hosting;
using DinoEditor.App.Input;
using DinoEditor.App.Services;
using DinoEditor.App.Services.Thumbnails;
using DinoEditor.App.ViewModels;
using DinoEditor.App.ViewModels.ContentDrawer;
using DinoEditor.App.Views;
using DinoEditor.Formats;
using DinoEditor.App.Projects;

namespace DinoEditor.App;

public partial class App : Application
{
    /// <summary>Parsed once in Program.Main and read here; Avalonia owns the lifetime, not us.</summary>
    public static CommandLine Cli { get; set; } = CommandLine.Parse(Array.Empty<string>());

    public static SettingsService Settings { get; } = new(SettingsService.DefaultSettingsPath);

    public LogViewModel LogVm { get; } = new();

    private readonly StatusBarViewModel _status = new();
    private readonly ViewportOverlayViewModel _overlayVm = new();

    private GameSession? _session;
    private CompositionViewportHost? _host;
    private RenderLoop? _loop;
    private EditorCameraController? _cameraController;

    /// <summary>Built on FIRST use, not at startup - see <see cref="OverrideCheckOnDemand"/>.</summary>
    private PatchdayIndex? _patchday;

    /// <summary>Built on FIRST use, not at startup - see <see cref="OverrideCheckOnDemand"/>.</summary>
    private TileProvenance? _provenance;
    private DockFactory? _factory;
    private ContentDrawerViewModel? _drawerVm;
    private ThumbnailService? _thumbs;
    private ViewportThumbnailBaker? _thumbBaker;
    private SelectionService? _selection;
    private GizmoController? _gizmo;
    private UndoService? _undo;
    private ProjectService? _project;
    private ExportService? _export;
    private DetailsViewModel? _detailsVm;
    private OutlinerViewModel? _outlinerVm;

    /// <summary>How far above an entity the ground-drop ray starts, in metres. A prop already
    /// sunk into the ground must still find the surface it is standing in.</summary>
    private const float GroundDropRayLiftMetres = 2f;

    /// <summary>Milliseconds since the Details panel last recomputed its camera distance.</summary>
    private double _detailsClock;

    /// <summary>True once the unsaved-changes guard has let the window close; see the Closing handler.</summary>
    private bool _closeApproved;

    public override void Initialize()
    {
        AvaloniaXamlLoader.Load(this);

        // The viewport document hands back the ONE live viewport control, so floating and re-docking
        // reparent it instead of rebuilding the GPU resources. Everything else is cheap to rebuild.
        DataTemplates.Add(new FuncDataTemplate<ViewportDocument>((d, _) => d?.View, true));
        DataTemplates.Add(new FuncDataTemplate<OutlinerTool>((_, _) => new OutlinerToolView { DataContext = _outlinerVm }, true));
        DataTemplates.Add(new FuncDataTemplate<DetailsTool>((_, _) => new DetailsToolView { DataContext = _detailsVm }, true));
        // The drawer VM and the thumbnail service do not exist yet (Initialize runs before
        // OnFrameworkInitializationCompleted); the lambda reads the fields when the dock actually
        // materialises the view, by which time both are wired.
        DataTemplates.Add(new FuncDataTemplate<ContentDrawerTool>(
            (_, _) => new ContentDrawerToolView { DataContext = _drawerVm, Thumbnails = _thumbs }, true));
        DataTemplates.Add(new FuncDataTemplate<OutputLogTool>((_, _) => new LogToolView { DataContext = LogVm }, true));
    }

    public override void OnFrameworkInitializationCompleted()
    {
        if (ApplicationLifetime is IClassicDesktopStyleApplicationLifetime desktop)
        {
            Settings.Load();
            LocalizationService.Instance.SetLanguage(Cli.Language ?? Settings.Current.Language);

            desktop.ShutdownMode = ShutdownMode.OnMainWindowClose;
            var main = new MainWindow();
            desktop.MainWindow = main;

            if (Cli.Smoke)
            {
                // --smoke: prove the window is created and the theme loads, then exit 0 without
                // touching the game install. This is the CI-safe start/exit check.
                var timer = new Avalonia.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(1500) };
                // _closeApproved: an unattended run must never stop on the unsaved-changes dialog.
                timer.Tick += (_, _) => { timer.Stop(); _closeApproved = true; desktop.Shutdown(0); };
                timer.Start();
                base.OnFrameworkInitializationCompleted();
                return;
            }

            if (Cli.ExitAfterSeconds is double seconds)
            {
                // --exit-after: a full real run (game data, world, render) that closes itself, so a
                // render check can be captured unattended. Not used by the product.
                var timer = new Avalonia.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(seconds) };
                // _closeApproved: an unattended run must never stop on the unsaved-changes dialog.
                timer.Tick += (_, _) => { timer.Stop(); _closeApproved = true; desktop.Shutdown(0); };
                timer.Start();
            }

            main.Opened += async (_, _) =>
            {
                // Wired before anything else in this handler can throw: from here on, an unhandled
                // exception on the UI thread reaches the dialog instead of taking the app down
                // silently.
                CrashHandler.ShowDialog = (detail, path) =>
                    Avalonia.Threading.Dispatcher.UIThread.Post(() =>
                    {
                        try { new ErrorDialog(detail, path).ShowDialog(main); }
                        catch (Exception) { /* the UI is already gone */ }
                    });

                Avalonia.Threading.Dispatcher.UIThread.UnhandledException += (_, e) =>
                {
                    CrashHandler.Report(e.Exception, "Dispatcher");
                    e.Handled = true;   // keep the shell alive; the render loop stops itself
                };

                main.Width = Settings.Current.WindowWidth;
                main.Height = Settings.Current.WindowHeight;

                if (Cli.ShotAfterSeconds is double shotSeconds && Cli.ShotPath is string shotPath)
                    ScheduleShot(main, shotSeconds, shotPath);

                if (!Settings.IsConfigured)
                {
                    var vm = new FirstRunViewModel(Settings);
                    bool ok = await new FirstRunDialog(vm).ShowDialog<bool>(main);
                    if (!ok) { desktop.Shutdown(0); return; }
                }

                _session = new GameSession(Settings, LogVm);
                _host = new CompositionViewportHost(LogVm.Write);

                // The project exists from startup - a mapper who opens the editor and drops one
                // prop is already working in an untitled project. Every mutation of it goes through
                // the undo service; the marshal callback puts a model change raised off the UI
                // thread back onto it before the renderer reads the rebuilt instance arrays.
                _undo = new UndoService();
                _project = new ProjectService(
                    _undo,
                    () => _session!.World,
                    () => _session!.Catalog,
                    action => Avalonia.Threading.Dispatcher.UIThread.Post(action),
                    // The GTA install is read-only for this editor. The service refuses to write
                    // anywhere inside it - manual save, Save As and the autosave tick alike - so the
                    // rule holds however the path arrived, picker or command line.
                    gameDir: () => Settings.Current.GameDir);
                // E1: importing a VANILLA tile has to record whether the BASE GAME ships it, or the
                // mapper can export a file the game silently ignores. Built on first use.
                _project.OverrideIgnoredBy = OverrideCheckOnDemand;

                // Ruling 4: an imported vanilla tile REPLACES Rockstar's copy rather than drawing
                // over it. Synced on every model change rather than only at import, so undo, redo,
                // closing a project and toggling a map's visibility all get it right for free.
                _project.Changed += SyncVanillaSuppression;

                // Ids restart at 2 in every project, so a selection that outlived a New or an Open
                // would re-bind to an unrelated entity. Drop it the moment the model is swapped.
                _project.Replaced += () => _selection?.Clear();

                _cameraController = new EditorCameraController(() => _session!.Core?.Camera)
                {
                    BaseSpeed = Settings.Current.CameraSpeed,
                };
                // Persist the fly speed on every wheel change (Drop 1: saving on each tick is
                // acceptable, Settings.Save is a small synchronous JSON write).
                _cameraController.SpeedChanged += speed =>
                {
                    Settings.Current.CameraSpeed = speed;
                    Settings.Save();
                };

                _drawerVm = new ContentDrawerViewModel(Settings.Current);
                // The service appends thumbs/v<version> itself, so it takes the cache root as-is.
                _thumbs = new ThumbnailService(
                    Settings.Current.CacheDir ?? SettingsService.SuggestCacheDir(),
                    () => _thumbBaker,
                    a => Avalonia.Threading.Dispatcher.UIThread.Post(a),
                    log: LogVm.Write);
                _thumbBaker = new ViewportThumbnailBaker(
                    () => _session!.Core,
                    () => _session!.World,
                    () => RenderLoop.Sun,
                    () => _loop?.FrameIndex ?? 0,
                    _session.Workers);
                _session.CatalogReady += cat => _drawerVm!.SetCatalog(cat);
                _drawerVm.GoToInstance = slot => GoToNearestInstance(slot);
                _drawerVm.CopyText = text => TopLevel.GetTopLevel(main)?.Clipboard?.SetTextAsync(text) ?? Task.CompletedTask;

                var viewportView = new ViewportView(_host, _cameraController, _overlayVm);

                // Built once and stored on the document, never by a data template: the document view
                // carries the composition host, and re-creating it on every re-template would leak
                // the D3D device rather than rebuild it.
                var documentView = new ViewportDocumentView(viewportView);

                // Selection: one service, three inputs (click, Esc, F) and three consumers (the
                // engine outline, the overlay label, the Focus button).
                _selection = new SelectionService();
                viewportView.Input!.Clicked += PickAt;
                viewportView.Input.EscapePressed += () => _selection.Clear();
                viewportView.Input.FocusRequested += FocusSelection;
                // Ctrl+Z / Ctrl+Y from the viewport. They go through the gizmo controller, not
                // straight to the undo service: UndoService throws while a drag's transient command
                // is pending, so the controller cancels the drag in flight first.
                viewportView.Input.UndoRequested += () => _gizmo!.Undo();
                viewportView.Input.RedoRequested += () => _gizmo!.Redo();
                _selection.Changed += () =>
                {
                    if (_session?.Core != null) SetCoreSelection(_session.Core, _selection);
                    // "A selection exists" is the Focus button's condition and only the selection
                    // service knows it; the per-frame label visibility is a separate flag.
                    _overlayVm.SetHasSelection(_selection.Primary != null);
                };
                documentView.AttachSelection(_overlayVm, FocusSelection);

                // The gizmo. It never sees the core: the screen ray, the world-to-DIP projector and
                // the gizmo's world length are the only things it needs from the camera, and all
                // three are read through the live core here so a device loss (which replaces the
                // core outright) costs the controller nothing.
                _gizmo = new GizmoController(
                    _selection, _project, _undo, ScreenRay, ProjectToDip, GizmoWorldLength);
                viewportView.Input.ModeRequested += mode => _gizmo.Mode = mode;
                viewportView.Input.CycleModeRequested += () => _gizmo.CycleMode();
                viewportView.Input.ToggleSpaceRequested += () => _gizmo.ToggleSpace();
                viewportView.Input.PointerHover += _gizmo.Hover;
                viewportView.Input.DragStarted += dip => _gizmo.TryBeginDrag(dip);
                viewportView.Input.Dragging += _gizmo.Drag;
                viewportView.Input.DragEnded += _ => _gizmo.EndDrag();
                viewportView.Input.DragCancelled += _gizmo.CancelDrag;
                // Ctrl inverts snapping while it is held. The behavior does not raise a modifier
                // event of its own, so the state is read off the key events as they bubble past.
                viewportView.Input.AddHandler(
                    Avalonia.Input.InputElement.KeyDownEvent,
                    (_, e) => _gizmo!.CtrlHeld = e.Key is Avalonia.Input.Key.LeftCtrl or Avalonia.Input.Key.RightCtrl
                        || e.KeyModifiers.HasFlag(Avalonia.Input.KeyModifiers.Control),
                    Avalonia.Interactivity.RoutingStrategies.Bubble,
                    handledEventsToo: true);
                viewportView.Input.AddHandler(
                    Avalonia.Input.InputElement.KeyUpEvent,
                    (_, e) =>
                    {
                        if (e.Key is Avalonia.Input.Key.LeftCtrl or Avalonia.Input.Key.RightCtrl)
                            _gizmo!.CtrlHeld = false;
                    },
                    Avalonia.Interactivity.RoutingStrategies.Bubble,
                    handledEventsToo: true);
                // Alt-tabbing away with Ctrl held must not leave snapping inverted forever.
                viewportView.Input.LostFocus += (_, _) => _gizmo!.CtrlHeld = false;

                // The edit keys and the browser drop. All four mutate the project through
                // UndoService.Execute, which throws while a gizmo drag's transient command is
                // pending, so all four go through GizmoController.RunEdit - the one place that
                // aborts the drag in flight first.
                viewportView.Input.DeleteRequested += () => _gizmo!.RunEdit(DeleteSelection);
                viewportView.Input.DuplicateRequested += () => _gizmo!.RunEdit(DuplicateSelection);
                viewportView.Input.GroundDropRequested += () => _gizmo!.RunEdit(GroundDropSelection);
                // Both drop events are subscribed on purpose: Dropped only fires for a payload
                // DragOverCheck accepted, and an unsubscribed check accepts nothing.
                viewportView.Input.DragOverCheck += (_, data) =>
                    Avalonia.Input.DataTransferExtensions.Contains(data, PlacementLogic.ArchetypeFormat);
                viewportView.Input.Dropped += (dip, data) => _gizmo!.RunEdit(() => PlaceFromPayload(dip, data));
                viewportView.Input.SetAllowDrop(true);

                documentView.AttachGizmo(_gizmo);

                // The Details panel reads the world, the catalog, the camera and the thumbnail
                // cache through lambdas: the session builds all four after this point, and the core
                // is rebuilt outright on device loss.
                _detailsVm = new DetailsViewModel(
                    _selection,
                    () => _session!.World,
                    () => _session!.Catalog,
                    () => _project,
                    () => _session!.Core?.Camera.Position ?? default,
                    hash => _thumbs!.TryGetDecoded(hash),
                    (hash, slot, cb) => _thumbs!.Request(hash, slot, cb))
                {
                    CopyText = text => TopLevel.GetTopLevel(main)?.Clipboard?.SetTextAsync(text) ?? Task.CompletedTask,
                    FocusPlacement = _ => FocusSelection(),
                    // A Details commit is a project mutation like any other, and UndoService.Execute
                    // throws while a gizmo drag holds a transient - the mapper can type in a box
                    // with a drag still in flight, so it goes through the same guard.
                    RunEdit = edit => _gizmo!.RunEdit(edit),
                };

                // The Outliner lists the world's ymaps; World is already built by the time
                // CatalogReady fires (GameSession.LoadAsync builds World, then the catalog).
                // Every layer edit the Outliner offers goes through UndoService, which throws while
                // a gizmo drag's transient command is pending, so they run through
                // GizmoController.RunEdit like the viewport's edit keys do.
                _outlinerVm = new OutlinerViewModel(_selection, _project)
                {
                    GoToYmap = GoToYmap,
                    RunEdit = edit => _gizmo!.RunEdit(edit),
                };
                _session.CatalogReady += _ => _outlinerVm.SetWorld(_session.World);

                _factory = new DockFactory(documentView, Settings.Current);
                var layout = _factory.CreateLayout();
                _factory.InitLayout(layout);
                main.DockControl.Factory = _factory;
                main.DockControl.Layout = layout;

                var mainVm = new MainWindowViewModel(LogVm, _status, _overlayVm, _project, _undo, _selection)
                {
                    ToggleDrawerTool = toolId => _factory!.ShowDrawerTool(toolId),
                    RequestExit = main.Close,
                    // The File and Edit commands mutate the project through UndoService like every
                    // other edit path, so they go through the same mid-drag guard. They also fire
                    // wherever focus is, including inside a Details edit box, and they move the
                    // entity under that box - so the caret is forgotten first and every box repaints
                    // from the new model. See the HAZARD note on DetailsViewModel.RefreshEditFields.
                    RunEdit = edit =>
                    {
                        _detailsVm?.ClearFocusedField();
                        _gizmo!.RunEdit(edit);
                    },
                    DeleteSelection = DeleteSelection,
                    // Delete must not blow away the selected entity while the mapper is typing.
                    IsTextInputFocused = () => main.FocusManager?.GetFocusedElement() is TextBox,
                    DuplicateSelection = DuplicateSelection,
                    PickSavePathAsync = () => PickProjectSavePathAsync(main),
                    PickOpenPathAsync = () => PickProjectOpenPathAsync(main),
                    PickExportFolderAsync = () => PickExportFolderAsync(main),
                    PickYmapFileAsync = () => PickYmapImportPathAsync(main),
                    PickGameYmapAsync = () => PickGameYmapAsync(main),
                    GameYmapCount = () => GameYmapEntries().Count,
                    FrameCameraOn = (centre, radius) =>
                    {
                        var cam = _session?.Core?.Camera;
                        if (cam == null) return;

                        // Back off far enough that the whole sphere fits the vertical FOV, with a
                        // little margin, and come in from the south-west and above - the angle a
                        // mapper reads a tile from, rather than straight down where nothing has a
                        // recognisable silhouette.
                        float dist = radius / MathF.Tan(cam.FovY * 0.5f) * 1.3f;
                        var dir = System.Numerics.Vector3.Normalize(new System.Numerics.Vector3(-0.6f, -0.6f, -0.52f));
                        cam.LookAt(centre - dir * dist, centre);
                    },
                    Export = _export = new ExportService(() => _session!.World, () => Settings.Current.GameDir),
                    CurrentProject = () => _project!.Current,
                    AskUnsavedAsync = () => new ConfirmUnsavedDialog().ShowDialog<UnsavedChoice>(main),
                    // The GTA install is read-only for this editor; a project file must never land
                    // inside it, whatever the picker returns.
                    GameDir = () => Settings.Current.GameDir,
                    ShowSettingsAsync = async () =>
                    {
                        var svm = new SettingsViewModel(Settings)
                        {
                            ApplyCameraSpeed = speed =>
                            {
                                if (_cameraController != null) _cameraController.BaseSpeed = speed;
                            },
                        };
                        await new SettingsDialog(svm).ShowDialog(main);
                        _factory!.RefreshTitles();
                    },
                };
                main.DataContext = mainVm;

                // The viewport's "go to location" popup. Wired here, after mainVm, so it can reuse
                // mainVm.FrameCameraOn - the same camera framing action an import uses - rather than
                // duplicating any camera code.
                var goToVm = new GoToLocationViewModel
                {
                    GameYmaps = () => (IReadOnlyList<YmapRecord>?)_session?.Data?.Ymaps ?? Array.Empty<YmapRecord>(),
                    GameDataForDedup = () => _session?.Data,
                    ProjectMaps = () => _project!.Current.Maps,
                    FrameCameraOn = mainVm.FrameCameraOn,
                };
                documentView.AttachGoTo(goToVm);

                // The unsaved-changes guard on every way out of the app: the X, Alt+F4 and the
                // File > Exit item (which just calls Close). The first Closing is always cancelled
                // so the question can be asked asynchronously; _closeApproved makes the second one
                // - raised by the Close below - go straight through.
                main.Closing += async (_, e) =>
                {
                    if (_closeApproved) return;
                    e.Cancel = true;
                    // A drag can still be in flight (Alt+F4 mid-drag). RunEdit reverts it, so a
                    // Save from the dialog writes the pre-drag transforms rather than half a drag.
                    mainVm.RunEdit(() => { });
                    if (await mainVm.ConfirmDiscardAsync())
                    {
                        _closeApproved = true;
                        main.Close();
                    }
                };

                mainVm.Banner.CopyToClipboardAsync = async text =>
                {
                    var clipboard = Avalonia.Controls.TopLevel.GetTopLevel(main)?.Clipboard;
                    if (clipboard != null) await clipboard.SetTextAsync(text);
                };

                // The status bar toggles show which drawer tool is open, so they follow the dock
                // rather than their own click history.
                _factory.DrawerStateChanged += (_, _) => mainVm.SetActiveDrawerTool(_factory!.ActiveDrawerToolId);
                mainVm.SetActiveDrawerTool(_factory.ActiveDrawerToolId);

                LocalizationService.Instance.LanguageChanged += (_, _) => _factory!.RefreshTitles();

                _loop = new RenderLoop(_host, _session, _cameraController, LogVm);
                // The gizmo is rebuilt from the selection before the frame is drawn rather than
                // owned by the engine. (--flight CHAINS its camera script in front of this hook
                // rather than replacing it, so a --place-demo flight still draws the gizmo of the
                // entity it selected.)
                _loop.BeforeUpdate = _ =>
                {
                    var core = _session?.Core;
                    if (core != null) core.GizmoToDraw = _gizmo?.State;
                };
                _loop.AfterRender = () => _thumbs!.Tick();
                // The old device took every in-flight readback with it; requeue those bakes. The
                // new core starts with no selection, so it has to be told again.
                _loop.DeviceLost = () => _thumbs?.OnDeviceLost();
                // Every core, the first one and every rebuild after a device loss, gets the
                // project's entities and the current selection: it is created empty.
                _loop.CoreAttached = AttachCore;
                _loop.Frame += stats =>
                {
                    _overlayVm.Update(stats);
                    UpdateSelectionLabel();
                    // Distance is the only Details field the camera moves. 4 Hz, like the rest of
                    // the telemetry: a metre of travel does not need a repaint at 120 FPS.
                    _detailsClock += stats.FrameMs;
                    if (_detailsClock >= 250) { _detailsClock = 0; _detailsVm?.RefreshDistance(); }
                    _status.Update(stats.FrameMs, stats.Fps, stats.CamPos, stats.Speed, stats.Resident, stats.VramBytes);
                    // The crash-recovery copy. TickAutosave is a couple of comparisons until the
                    // interval is up, and DateTime.UtcNow is the same clock ProjectService defaults
                    // to, so the two-minute gap it measures is real.
                    _project?.TickAutosave(DateTime.UtcNow);
                };
                _loop.Failure += message => Avalonia.Threading.Dispatcher.UIThread.Post(() =>
                    mainVm.Banner.Show(message, message));

                _session.PhaseChanged += (_, phase) => Avalonia.Threading.Dispatcher.UIThread.Post(() =>
                    _status.SetPhaseKey(phase switch
                    {
                        SessionPhase.OpeningGameData => "Status.Loading",
                        SessionPhase.BuildingWorld => "Status.BuildingWorld",
                        SessionPhase.Running => "Status.Ready",
                        _ => "Status.Loading",
                    }));

                await _session.LoadAsync(CancellationToken.None);
                if (_session.Phase == SessionPhase.Failed)
                {
                    string message = LocalizationService.Instance.Format(
                        "Session.LoadFailed", _session.FailureText ?? string.Empty);
                    LogVm.Write(message);
                    mainVm.Banner.Show(message, _session.FailureText ?? string.Empty);
                    return;
                }

                _loop.Start();

                bool opened = Cli.OpenPath is string openPath && OpenProjectFromCli(openPath);
                if (Cli.ImportVanilla is string stem) opened |= ImportVanillaFromCli(stem);
                if (Cli.LiftArchetype is string liftName) LiftFromCli(liftName, Cli.Lift);
                if (Cli.AsAuthored) AsAuthoredFromCli();
                if (Cli.RenameTo is string newName) RenameFromCli(newName);

                if (Cli.PickAt is (int pickX, int pickY)) SchedulePick(pickX, pickY);

                if (Cli.PlaceDemo > 0) SchedulePlaceDemo(Cli.PlaceDemo);
                else if (opened) { SaveDemoProject(); ExportDemoProject(); }
                else
                {
                    if (Cli.SaveDemoPath is string ignored)
                        LogVm.Write($"[save-demo] ignored: {ignored} needs --place-demo or a project " +
                            "that --open loaded; nothing was written");
                    if (Cli.ExportDemoFolder is string ignoredExport)
                        LogVm.Write($"[export-demo] ignored: {ignoredExport} needs --place-demo or a " +
                            "project that --open loaded; nothing was written");
                }

                if (Cli.Flight)
                {
                    // --flight: the benchmark harness drives the camera through the product render
                    // loop, writes docs/app-drop1/ and closes the window. Not a product path.
                    string outDir = GameSessionPaths.FlightOutDir;
                    var flight = new AppFlight(_loop, _session, _cameraController, main, LogVm, outDir,
                        _thumbs, () => _session!.Catalog, Cli.BakeThumbs,
                        () => _project?.Current.Entities.Count ?? 0);
                    flight.Finished += () => Avalonia.Threading.Dispatcher.UIThread.Post(() =>
                    {
                        _closeApproved = true;   // the benchmark closes itself; no dialog in the way
                        main.Close();
                    });
                    flight.Attach();
                }
            };

            desktop.Exit += (_, _) =>
            {
                // --shot-after resizes the drawer for the capture; persisting that would leave the
                // next real run with a screenshot layout.
                if (Cli.ShotAfterSeconds == null) _factory?.SaveProportions(Settings.Current);
                Settings.Current.WindowWidth = main.Width;
                Settings.Current.WindowHeight = main.Height;
                if (!Settings.Save())
                    LogVm.Write(LocalizationService.Instance["Settings.SaveFailed"]);

                _loop?.Stop();
                // Before the session: the baker reaches into the session's ViewportCore, so the
                // thumbnail workers must be stopped while that core is still alive.
                _thumbs?.Dispose();
                _session?.Dispose();
                _host?.Dispose();
            };
        }

        base.OnFrameworkInitializationCompleted();
    }

    /// <summary>--shot-after: opens the Content Drawer on a stock query, waits for the session and
    /// the thumbnail bakes to settle, and writes one whole-window PNG. The window stays open, so an
    /// --exit-after on the same command line still owns the shutdown. Development aid only.</summary>
    private void ScheduleShot(Window main, double seconds, string path)
    {
        // The grid has to be populated before the shot or the screenshot proves nothing, and the
        // bakes need time, so the query goes in well ahead of the capture.
        const double SearchLeadSeconds = 10;
        double searchAt = Math.Max(1, seconds - SearchLeadSeconds);

        // A --pick-at or --place-demo shot is about the viewport, the gizmo, the Details panel and
        // the Outliner: opening the Content Drawer at half the window would bury the very thing
        // being proven, so the prime step is skipped and only the capture is scheduled.
        if (Cli.PickAt != null || Cli.PlaceDemo > 0) { ScheduleCapture(main, seconds, path); return; }

        var prime = new Avalonia.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(searchAt) };
        prime.Tick += (_, _) =>
        {
            prime.Stop();
            if (_factory != null && _factory.ActiveDrawerToolId != "ContentDrawer")
                _factory.ShowDrawerTool("ContentDrawer");
            if (_factory != null)
            {
                // The drawer opens at the UE-ish 22% of the window, which is a couple of rows of
                // thumbnails short. The shot is a check on the grid, so it gets a taller drawer;
                // SaveProportions on exit would persist this, so the settings write is skipped
                // instead of the drawer being left resized for the next real run.
                _factory.DrawerDock.Proportion = 0.5;
                _factory.DocumentDock.Proportion = 0.5;
            }
            if (_drawerVm != null) _drawerVm.SearchText = "chair";
            LogVm.Write("[shot] drawer primed with query 'chair'");
        };
        prime.Start();

        ScheduleCapture(main, seconds, path);
    }

    /// <summary>The capture half of --shot-after: one whole-window PNG at the requested second.</summary>
    private void ScheduleCapture(Window main, double seconds, string path)
    {
        var shot = new Avalonia.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(seconds) };
        shot.Tick += (_, _) =>
        {
            shot.Stop();
            try
            {
                Flight.WindowCapture.Capture(main.TryGetPlatformHandle()?.Handle ?? IntPtr.Zero, path);
                LogVm.Write($"[shot] wrote {path}");
            }
            catch (Exception ex) { LogVm.Write($"[shot] capture failed: {ex.Message}"); }
        };
        shot.Start();
    }

    /// <summary>--pick-at: issues one synthetic click at the given viewport DIPs once the stream has
    /// SETTLED, and leaves the selection in place so a later --shot-after captures the outline, the
    /// label, the Details panel and the Outliner highlight. Development aid only.
    /// <para/>
    /// It used to fire on a flat two-second timer, and that was wrong: downtown spends ~3 s just
    /// pinning SLOD archetypes, so at two seconds most of what is under the cursor is requested but
    /// not yet resident. Picking deliberately ignores archetypes whose geometry has not arrived (a
    /// click must not select something that is not on screen), so the early click reported "hit
    /// nothing" on a building that renders perfectly well a few seconds later. Waiting for the three
    /// stream queues to be empty for two consecutive ticks tests what the user would actually see;
    /// the 20 s cap keeps the harness bounded if the queues never drain.</summary>
    private void SchedulePick(int x, int y) => WhenStreamSettled("pick-at", () =>
        {
            PickAt(new Avalonia.Point(x, y), Avalonia.Input.KeyModifiers.None);
            if (_selection?.Primary is DinoEditor.Viewport.Picking.SelectionTarget hit
                && TryResolveSelection(out var hitPos, out _))
            {
                LogVm.Write($"[pick-at] {x},{y} hit {hit.Kind} {hit.Index} '{PrimarySelectionName()}' " +
                            $"at {hitPos.X:F1},{hitPos.Y:F1},{hitPos.Z:F1}");
            }
            else
            {
                LogVm.Write($"[pick-at] {x},{y} hit nothing");
            }

            // Why the pick landed where it did. Costs nothing (the counters are already filled) and
            // is the difference between "the click does nothing" and knowing which phase dropped it.
            var s = DinoEditor.Viewport.Picking.Picker.LastStats;
            LogVm.Write($"[pick-at] stats candidates={s.Candidates} visited={s.Visited} filtered={s.FilteredOut} " +
                        $"box={s.BoxHits} degenerate={s.DegenerateBoxes} pruned={s.PrunedByDistance} " +
                        $"meshNull={s.MeshNull} noTri={s.NoTriangle} tri={s.TriangleHits}");
        });

    /// <summary>
    /// Runs <paramref name="then"/> on the UI thread once the three streaming queues have been
    /// empty for two consecutive polls - "what the user would actually see" rather than "the render
    /// loop has started". The 20 s cap keeps an unattended harness bounded if the queues never
    /// drain. <paramref name="tag"/> only names the log line.
    /// </summary>
    private void WhenStreamSettled(string tag, Action then)
    {
        const int PollMs = 250;
        const int QuietTicksRequired = 2;
        const int MaxWaitMs = 20_000;

        int waited = 0, quiet = 0;
        var timer = new Avalonia.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(PollMs) };
        timer.Tick += (_, _) =>
        {
            waited += PollMs;
            var cache = _session?.Core?.Cache;
            bool idle = cache != null && cache.RequestQueueDepth == 0 && cache.InFlightCount == 0
                        && cache.ReadyQueueDepth == 0;
            quiet = idle ? quiet + 1 : 0;
            if (quiet < QuietTicksRequired && waited < MaxWaitMs) return;

            timer.Stop();
            LogVm.Write($"[{tag}] stream settled after {waited / 1000.0:F1}s " +
                        $"({_session?.Core?.Cache.ResidentCount ?? 0:N0} archetypes resident)");
            then();
        };
        timer.Start();
    }

    // ---- --place-demo / --save-demo / --open -------------------------------------------------
    //
    // The three development aids that let the edit layer be driven without a person at the mouse:
    // place a block of props, write the project, and read one back. The product never passes them.

    /// <summary>The archetype --place-demo prefers; anything placed in the vanilla map does as a
    /// fallback, but a chair is small, cheap to decode and unmistakable in a screenshot.</summary>
    private const string DemoArchetypeName = "prop_chair_01a";

    /// <summary>How high above the camera the ground ray for a demo prop starts, in metres. The
    /// camera is above the ground, so this only has to clear the camera itself.</summary>
    private const float DemoGroundRayLiftMetres = 2f;

    /// <summary>--place-demo: waits for the stream, drops the grid, then writes --save-demo if it
    /// was asked for. Under --flight the queues never settle (the camera is moving the whole time),
    /// so the props go in on a flat two-second timer instead - which is still the flight's own start
    /// camera, since the flight primes for three seconds before it moves.</summary>
    private void SchedulePlaceDemo(int count)
    {
        if (Cli.Flight)
        {
            var timer = new Avalonia.Threading.DispatcherTimer { Interval = TimeSpan.FromSeconds(2) };
            timer.Tick += (_, _) =>
            {
                timer.Stop(); PlaceDemoEntities(count); SaveDemoProject(); ExportDemoProject();
            };
            timer.Start();
            return;
        }

        WhenStreamSettled("place-demo", () =>
        {
            PlaceDemoEntities(count); SaveDemoProject(); ExportDemoProject();
        });
    }

    /// <summary>Places <paramref name="count"/> props on the ground in front of the camera, selects
    /// the first and switches the gizmo to Translate - exactly the state a mapper is in right after
    /// dropping something out of the browser. Each prop is its own Place command, so this pushes
    /// COUNT undo entries rather than one; left that way because it is a development aid, not an
    /// edit path a mapper drives.</summary>
    private void PlaceDemoEntities(int count)
    {
        var core = _session?.Core;
        if (core == null || _project == null || _selection == null || _gizmo == null) return;

        if (!TryFindDemoArchetype(out int hash, out string name))
        {
            LogVm.Write("[place-demo] no placed archetype in the catalog; nothing to place");
            return;
        }

        var positions = PlacementLogic.DemoGridPositions(core.Camera.Position, core.Camera.Forward, count);
        float baseOffset = ArchetypeBaseOffset(hash);
        int grounded = 0;
        DinoEditor.App.Projects.ProjectEntity? first = null;

        // One RunEdit for the whole block: it is the same mid-drag guard every other edit path
        // uses, and there is no reason to take it 50 times.
        _gizmo.RunEdit(() =>
        {
            foreach (var slot in positions)
            {
                var position = slot;
                var origin = new System.Numerics.Vector3(
                    slot.X, slot.Y, core.Camera.Position.Z + DemoGroundRayLiftMetres);
                var ray = new DinoEditor.Viewport.Picking.Ray(origin, -System.Numerics.Vector3.UnitZ);
                if (core.PickRay(ray, null) is DinoEditor.Viewport.Picking.PickResult hit)
                {
                    position.Z = PlacementLogic.GroundDropPosition(hit.HitPoint.Z, baseOffset, 1f);
                    grounded++;
                }

                var entity = _project.Place(hash, name, position, System.Numerics.Quaternion.Identity, 1f);
                first ??= entity;
            }
        });

        if (first == null) return;

        _selection.Select(new DinoEditor.Viewport.Picking.SelectionTarget(
            DinoEditor.Viewport.Picking.SelectionKind.Project, first.Id));
        _gizmo.Mode = DinoEditor.Viewport.Gizmo.GizmoMode.Translate;
        // The props sit on the ground, which is metres BELOW a camera looking at the skyline, so
        // the block would be off the bottom of the frame. The camera is turned to face it - not
        // moved, so the shot is still the view the flight and the other screenshots use.
        core.Camera.LookAt(core.Camera.Position, first.Position);
        LogVm.Write($"[place-demo] placed {positions.Count} x '{name}' ({grounded} on ground) " +
                    $"from {first.Position.X:F1},{first.Position.Y:F1},{first.Position.Z:F1}");
    }

    /// <summary>The archetype --place-demo uses: <see cref="DemoArchetypeName"/> when the map has
    /// it, otherwise the first catalog entry that is actually placed somewhere in the vanilla map
    /// (an archetype with no instances may have no loadable container behind it).</summary>
    private bool TryFindDemoArchetype(out int hash, out string name)
    {
        hash = 0;
        name = string.Empty;

        var catalog = _session?.Catalog;
        if (catalog == null) return false;

        foreach (var entry in catalog.Entries)
        {
            if (entry.Name == DemoArchetypeName) { hash = entry.NameHash; name = entry.Name; return true; }
        }

        foreach (var entry in catalog.Entries)
        {
            if (entry.HasName && entry.InstanceCount > 0)
            {
                hash = entry.NameHash;
                name = entry.Name;
                return true;
            }
        }

        return false;
    }

    /// <summary>--save-demo: writes the project where the command line asked. No game-directory
    /// check here - ProjectService refuses that path itself, at the one place that writes.</summary>
    private void SaveDemoProject()
    {
        if (Cli.SaveDemoPath is not string path || _project == null) return;

        var (ok, error) = _project.SaveAs(path);
        LogVm.Write(ok
            ? $"[save-demo] wrote {path}, {_project.Current.Entities.Count} entities"
            : $"[save-demo] failed: {error}");
    }

    /// <summary>--export-demo: exports the open project into the folder the command line named, so
    /// the production bench gets a resource to `ensure` without a person at the folder picker. Like
    /// --save-demo it does no game-directory check of its own: ExportService refuses that path at
    /// the one place that writes, and duplicating the guard here is how the two drift apart.</summary>
    private void ExportDemoProject()
    {
        if (Cli.ExportDemoFolder is not string folder || _export == null || _project == null) return;

        var (result, error) = _export.Export(_project.Current, folder);
        if (result == null) { LogVm.Write($"[export-demo] failed: {error}"); return; }

        LogVm.Write($"[export-demo] wrote {result.YmapPath}, {result.EntityCount} entities" +
            (result.ScaleStripped > 0 ? $", {result.ScaleStripped} scaled down to 1" : "") +
            (result.FxManifestWritten ? ", fxmanifest.lua created" : ", fxmanifest.lua already present"));
    }

    /// <summary>--open: loads a project at startup and selects its first entity, so a --shot-after
    /// on the same command line captures what came back off disk. Returns true when the project
    /// really opened, so the caller can decide whether --save-demo has anything to write.</summary>
    private bool OpenProjectFromCli(string path)
    {
        if (_project == null) return false;

        var (ok, error, notice) = _project.Open(path);
        if (!ok) { LogVm.Write($"[project] open failed: {error}"); return false; }

        LogVm.Write($"[project] opened {path}, {_project.Current.Entities.Count} entities");
        // Opened from inside the read-only install: it came back with no path, so a later save has
        // to be given one. Said out loud rather than left for the mapper to discover at Ctrl+S.
        if (notice != null) LogVm.Write($"[project] {notice}");

        if (_project.Current.Entities.Count == 0 || _selection == null || _gizmo == null) return true;
        _selection.Select(new DinoEditor.Viewport.Picking.SelectionTarget(
            DinoEditor.Viewport.Picking.SelectionKind.Project, _project.Current.Entities[0].Id));
        _gizmo.Mode = DinoEditor.Viewport.Gizmo.GizmoMode.Translate;
        return true;
    }

    /// <summary>World-space ray through a viewport position in DIPs, for the gizmo hit test and its
    /// drag solvers. Returns a degenerate ray (zero direction, which every solver rejects) while
    /// there is no core or no surface to measure.</summary>
    private DinoEditor.Viewport.Picking.Ray ScreenRay(Avalonia.Point dip)
    {
        var core = _session?.Core;
        if (core == null || _host == null) return default;

        var size = _host.PixelSize;
        if (size.Width <= 0 || size.Height <= 0) return default;

        double scale = size.Width / Math.Max(1.0, _host.Bounds.Width);
        return core.Camera.ScreenRay((float)(dip.X * scale), (float)(dip.Y * scale), size.Width, size.Height);
    }

    /// <summary>Projects a world point to viewport DIPs - the same space the pointer positions
    /// arrive in, which is what the uniform-scale solver measures its two distances in. Returns NaN
    /// for a point behind the camera or with no core, and the solver holds its last factor.</summary>
    private System.Numerics.Vector2 ProjectToDip(System.Numerics.Vector3 world)
    {
        var core = _session?.Core;
        var nowhere = new System.Numerics.Vector2(float.NaN, float.NaN);
        if (core == null || _host == null) return nowhere;

        var clip = System.Numerics.Vector4.Transform(
            new System.Numerics.Vector4(world, 1f), core.LastViewProj);
        if (clip.W <= 0f) return nowhere;

        double widthDip = Math.Max(1.0, _host.Bounds.Width);
        double heightDip = Math.Max(1.0, _host.Bounds.Height);
        return new System.Numerics.Vector2(
            (float)((clip.X / clip.W + 1.0) / 2.0 * widthDip),
            (float)((1.0 - clip.Y / clip.W) / 2.0 * heightDip));
    }

    /// <summary>The world length of one gizmo axis, taken from the core so the hit test uses exactly
    /// the size the renderer draws.</summary>
    private float GizmoWorldLength(DinoEditor.Viewport.Gizmo.GizmoState state)
    {
        var core = _session?.Core;
        if (core == null || _host == null) return 0f;
        return core.GizmoWorldLength(state, _host.PixelSize.Height);
    }

    /// <summary>Hangs the per-core state off a freshly created ViewportCore: the project's entity
    /// source and the current selection. A new core has neither, and a device loss in the middle of
    /// a session must not drop the mapper's work off the screen.</summary>
    private void AttachCore()
    {
        var core = _session?.Core;
        if (core == null) return;
        core.DynamicEntities = _project?.Source;
        SetCoreSelection(core, _selection);

        // A new core means a NEW WorldGrid, and a fresh grid suppresses nothing. Without this the
        // project's imported vanilla tiles come back the moment the device is recreated, and - the
        // common case - opening a .dinoproj never suppressed them at all, because the project
        // raises Changed before the world exists and SyncVanillaSuppression returns early on a
        // null grid. Re-applying here is idempotent: SetYmapSuppressed early-returns when the set
        // already agrees.
        SyncVanillaSuppression();
    }

    /// <summary>Pushes the app's selection set into the engine's typed selection list, which is what
    /// the outline pass walks.</summary>
    private static void SetCoreSelection(DinoEditor.Viewport.ViewportCore core, SelectionService? selection)
    {
        core.Selection.Clear();
        if (selection == null) return;
        foreach (var target in selection.Targets) core.Selection.Add(target);
    }

    /// <summary>Left click: turns the DIP position into viewport pixels, asks the engine what is
    /// under it, and selects it. Ctrl adds the hit to the selection or removes it if it was already
    /// there; a plain click replaces the whole selection, and a plain click on nothing clears it.
    /// Ctrl+click on nothing leaves the selection alone - a miss while extending a selection is a
    /// slip, not an instruction to throw the set away.</summary>
    private void PickAt(Avalonia.Point dip, Avalonia.Input.KeyModifiers modifiers)
    {
        if (_selection == null || _session?.Core == null) return;
        var hit = PickUnder(dip, IsLockedTarget);

        bool ctrl = modifiers.HasFlag(Avalonia.Input.KeyModifiers.Control);
        if (hit is not DinoEditor.Viewport.Picking.PickResult result)
        {
            if (!ctrl) _selection.Clear();
            return;
        }

        if (ctrl) _selection.Toggle(result.Target);
        else _selection.Select(result.Target);
    }

    /// <summary>Asks the engine what is under a viewport position in DIPs. Null when there is no
    /// core or surface yet, or when the ray hit nothing.</summary>
    private DinoEditor.Viewport.Picking.PickResult? PickUnder(
        Avalonia.Point dip, Func<DinoEditor.Viewport.Picking.SelectionTarget, bool>? exclude)
    {
        var core = _session?.Core;
        if (core == null || _host == null) return null;

        var size = _host.PixelSize;
        if (size.Width <= 0 || size.Height <= 0) return null;

        // Avalonia reports pointer positions in DIPs; the D3D viewport is in pixels, same top-left
        // origin, so a single scale factor converts between them.
        double scale = size.Width / Math.Max(1.0, _host.Bounds.Width);
        return core.Pick((float)(dip.X * scale), (float)(dip.Y * scale), size.Width, size.Height, exclude);
    }

    // ---- project file pickers ---------------------------------------------------------------
    //
    // Both start in the folder the last project came from (AppSettings.LastProjectDir) and both
    // remember the folder they end in, so a mapper working out of one project folder never has to
    // navigate to it twice. The picker itself is the only part of the File commands that needs a
    // window, which is why it lives here rather than in the view model.

    /// <summary>Extension of a project file, without the dot.</summary>
    private const string ProjectExtension = "dinoproj";

    /// <summary>
    /// Picks a loose <c>.ymap</c> to import. Deliberately does NOT start in the GTA install: a tile
    /// out of the game is the separate vanilla path, and the install is read-only to this editor
    /// anyway. It starts where the last project was, which is where a mapper's own resource folders
    /// tend to sit.
    /// </summary>
    private async Task<string?> PickYmapImportPathAsync(Window main)
    {
        var storage = TopLevel.GetTopLevel(main)?.StorageProvider;
        if (storage == null) return null;

        var files = await storage.OpenFilePickerAsync(new FilePickerOpenOptions
        {
            Title = LocalizationService.Instance["Import.PickFile"],
            AllowMultiple = false,
            FileTypeFilter = new[] { YmapFileType() },
            SuggestedStartLocation = await LastImportFolderAsync(storage),
        });

        return RememberImportFolder(files.Count > 0 ? files[0].TryGetLocalPath() : null);
    }

    /// <summary>
    /// Whether a given vanilla tile can be overridden at all (E1), building both indexes the first
    /// time it is asked and keeping them for the session.
    /// </summary>
    /// <remarks>
    /// THE VERDICT COMES FROM <see cref="TileProvenance"/>, NOT FROM <see cref="PatchdayIndex"/>.
    /// Patchday is kept for the pack names it reports, which are information the mapper may want,
    /// but it scans <c>patchday*</c> only - the right shape of scan over the wrong set of packs -
    /// and six in-game runs measured the rule as "the base game ships it".
    ///
    /// Lazy on purpose. Provenance walks every x64 archive, update/common and all 92 dlc.rpf for
    /// their .ymap NAMES, MEASURED at 2.4s over 10,647 names on the reference install; patchday
    /// pays a further 0.3s for 32 of those packs. Cheap, but only the vanilla-edit path ever needs
    /// either, so a mapper who never imports a base-game tile should not pay at startup. Neither is
    /// cached to disk: seconds do not justify a cache format to keep in step with the install.
    /// </remarks>
    private OverrideCheck OverrideCheckOnDemand(string tileName)
    {
        // Same temp root GameSession uses.
        string temp = Path.Combine(Path.GetTempPath(), "DinoEditor");

        _provenance ??= TileProvenance.Build(Settings.Current.GameDir, temp, m => LogVm.Write(m));
        _patchday ??= PatchdayIndex.Build(Settings.Current.GameDir, temp, m => LogVm.Write(m));

        // The scan caveats travel with the answer rather than staying in the log: a FALSE verdict
        // from an incomplete scan means "not found", not "not shipped", and the mapper is the one
        // who needs to know that before shipping the file.
        return new OverrideCheck(_patchday.PacksShipping(tileName), _patchday.PacksIncomplete)
        {
            ShippedByBaseGame = _provenance.IsShippedByBaseGame(tileName),
            UnscannedArchives = _provenance.ArchivesIncomplete,
        };
    }

    /// <summary>
    /// Hides the vanilla tiles that imported maps are replacing, and restores any that are no
    /// longer being replaced.
    /// </summary>
    /// <remarks>
    /// Driven off <c>ProjectService.Changed</c> and computed from scratch each time, because that
    /// is the only version that cannot drift: undo of an import, a map switched invisible, a
    /// project closed and another opened all reduce to "which vanilla ymaps should be hidden right
    /// now". Tracking deltas at each call site is how one of those paths ends up leaving Rockstar's
    /// copy hidden with nothing in its place.
    ///
    /// Matching is by NAME against <c>Region.YmapNames</c>, which is the same identity the engine
    /// resolves an override by, and the same one <c>MapDocument.Name</c> carries for an imported
    /// map.
    /// </remarks>
    private void SyncVanillaSuppression()
    {
        var grid = _session?.Core?.Grid;
        var region = _session?.World;
        if (grid == null || region == null || _project == null) return;

        var wanted = VanillaSuppression.WantedIndices(_project.Current.Maps, region.YmapNames);

        foreach (int index in grid.SuppressedYmaps.Where(i => !wanted.Contains(i)).ToArray())
            grid.SetYmapSuppressed(index, false);

        foreach (int index in wanted) grid.SetYmapSuppressed(index, true);
    }

    /// <summary>The .ymap entries indexed out of the install, or empty when it has not finished
    /// loading. Empty is a real state on startup, not an error.</summary>
    /// <summary>
    /// --import-vanilla: imports one base-game tile by name through the SAME
    /// <see cref="ProjectService.ImportMap"/> the Import button uses, so the bench loads what the
    /// editor really produces. Returns whether a map was imported, which is what makes the existing
    /// --save-demo / --export-demo step run.
    /// </summary>
    /// <remarks>
    /// The entry is matched by NAME against the session's own index and REFUSED when the name is
    /// ambiguous rather than silently taking the first. Several tiles ship more than one copy
    /// across the archive chain (dt1_21_prop_lift has four), and a bench result attributed to the
    /// wrong copy is worse than no result - it is a measurement of something nobody identified.
    /// </remarks>
    private bool ImportVanillaFromCli(string stem)
    {
        var matches = GameYmapEntries()
            .Where(e => string.Equals(e.NameNoExt, stem, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (matches.Count == 0)
        {
            LogVm.Write($"[import-vanilla] {stem}.ymap is not in the install index; nothing imported");
            return false;
        }

        if (matches.Count > 1)
        {
            LogVm.Write($"[import-vanilla] {stem}.ymap has {matches.Count} copies in the install - refusing " +
                        "rather than guessing which one:");
            foreach (var m in matches) LogVm.Write($"[import-vanilla]   {m.FullPath}");
            return false;
        }

        var record = FastMapReader.ParseYmap(matches[0]);
        if (_project == null) { LogVm.Write("[import-vanilla] no project service"); return false; }

        var (map, result, error) = _project.ImportMap(record, MapOrigin.ImportedVanilla);
        if (map == null)
        {
            LogVm.Write($"[import-vanilla] refused: {error}");
            return false;
        }

        LogVm.Write($"[import-vanilla] {stem}: {result!.EntitiesRead} entities, " +
                    $"{map.PhysicsDictionaries.Count} physics dictionaries, " +
                    $"blocks={(map.UnsupportedBlocks == YmapBlocks.None ? "none" : YmapBlocksNames.Join(map.UnsupportedBlocks))}, " +
                    $"from {matches[0].FullPath}");
        return true;
    }

    /// <summary>
    /// --lift: raises every entity of one archetype in the active map. A bench harness, not a
    /// product path.
    /// </summary>
    /// <remarks>
    /// WHY A BENCH RUN NEEDS THIS AT ALL. An override experiment replaces a vanilla tile with our
    /// copy of it. If the copy is faithful, a successful load and a total failure produce the same
    /// view - the props are where Rockstar put them either way - so the run cannot be read. Moving
    /// a known archetype by a known amount is what makes "our file loaded" measurable, and it is
    /// the same trick every E1 run used.
    ///
    /// The match is by NAME, resolved to the archetype hash the same lowercased-joaat way the rest
    /// of the pipeline resolves one, and it REPORTS THE COUNT - a silent zero would produce a file
    /// identical to vanilla and a bench run whose green result meant nothing.
    /// </remarks>
    private void LiftFromCli(string archetypeName, float metres)
    {
        if (_project == null) { LogVm.Write("[lift] no project service"); return; }

        int hash = Jenkins.HashLowerI(archetypeName);
        var map = _project.Current.ActiveMap;
        int moved = 0;
        foreach (var e in map.Entities)
        {
            if (e.ArchetypeHash != hash) continue;
            e.Position = new System.Numerics.Vector3(e.Position.X, e.Position.Y, e.Position.Z + metres);
            moved++;
        }

        LogVm.Write(moved == 0
            ? $"[lift] NOTHING MOVED: no entity in \"{map.Name}\" has archetype {archetypeName} " +
              $"(hash 0x{hash:X8}) - the export would be identical to the vanilla file"
            : $"[lift] raised {moved} x {archetypeName} by {metres:F1} m");
    }

    /// <summary>--as-authored: drops the map's pinned status so export names the file after the
    /// map rather than after the tile it replaces. Bench harness; see CommandLine.AsAuthored.</summary>
    private void AsAuthoredFromCli()
    {
        if (_project == null) { LogVm.Write("[as-authored] no project service"); return; }
        var map = _project.Current.ActiveMap;
        map.Origin = MapOrigin.Authored;
        map.AutoPartition = true;
        LogVm.Write($"[as-authored] \"{map.Name}\" is now an authored map; " +
                    "the pinned parent hash and source flags are dropped");
    }

    /// <summary>--rename: renames the active map, and with it the exported file name and the
    /// internal name hash, which ExportService derives from the same string.</summary>
    private void RenameFromCli(string newName)
    {
        if (_project == null) { LogVm.Write("[rename] no project service"); return; }
        var map = _project.Current.ActiveMap;
        string was = map.Name;
        LogVm.Write(_project.RenameMap(map.Id, newName)
            ? $"[rename] \"{was}\" -> \"{map.Name}\""
            : $"[rename] refused: \"{was}\" -> \"{newName}\"");
    }

    private IReadOnlyList<RpfEntry> GameYmapEntries() =>
        _session?.Data?.Index is { } index && index.ByExt.TryGetValue(".ymap", out var ymaps)
            ? ymaps
            : Array.Empty<RpfEntry>();

    /// <summary>
    /// Shows the browser over the ymaps indexed out of the GTA V install and returns the chosen
    /// entry, or null when the mapper cancelled.
    /// </summary>
    private async Task<RpfEntry?> PickGameYmapAsync(Window main)
    {
        var ymaps = GameYmapEntries();
        if (ymaps.Count == 0) return null;   // the view model reports this; see GameYmapCount

        var vm = new YmapBrowserViewModel(ymaps);
