    /// <summary>Where the last import came from, falling back to the last project folder on the
    /// very first import. A ymap lives in a resource's stream/ folder, which is nowhere near where
    /// projects are kept, so reusing LastProjectDir forever would open the picker in the wrong place
    /// every single time.</summary>
    private static async Task<IStorageFolder?> LastImportFolderAsync(IStorageProvider storage)
    {
        string? dir = Settings.Current.LastImportDir;
        if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir)) return await LastProjectFolderAsync(storage);

        try { return await storage.TryGetFolderFromPathAsync(dir); }
        catch (Exception) { return null; }   // an unreachable path must not take the picker down
    }

    private static string? RememberImportFolder(string? path)
    {
        if (string.IsNullOrEmpty(path)) return path;

        string? dir = Path.GetDirectoryName(path);
        if (!string.IsNullOrEmpty(dir) && dir != Settings.Current.LastImportDir)
        {
            Settings.Current.LastImportDir = dir;
            Settings.Save();
        }

        return path;
    }

