    /// <summary>Picking filter: a project entity on a locked layer is not selectable, so the ray
    /// falls through it onto whatever is behind.</summary>
    private bool IsLockedTarget(DinoEditor.Viewport.Picking.SelectionTarget target) =>
        target.Kind == DinoEditor.Viewport.Picking.SelectionKind.Project
        && (_project?.IsLocked(target.Index) ?? false);

    // ---- edit commands driven from the viewport ---------------------------------------------
    //
    // All four run inside GizmoController.RunEdit (see the wiring above), so none of them can be
    // reached while a gizmo drag holds a transient undo command.

    /// <summary>
    /// A prop dropped out of the Content Browser. It lands where the drop ray hits geometry, or
    /// <see cref="PlacementLogic.FallbackDistanceMetres"/> in front of the camera when the mapper
    /// dropped it on empty sky. The new entity is selected and the gizmo switches to Translate, so
    /// it can be nudged into place immediately - the same thing Unreal does with a new actor.
    /// </summary>
    private void PlaceFromPayload(Avalonia.Point dip, Avalonia.Input.IDataTransfer data)
    {
        if (_project == null || _selection == null || _gizmo == null) return;

        // A foreign payload must be rejected, not throw out of a drop handler.
        if (!PlacementLogic.TryDecodePayload(
                Avalonia.Input.DataTransferExtensions.TryGetValue(data, PlacementLogic.ArchetypeFormat),
                out int hash, out _, out string name))
        {
            return;
        }

        var core = _session?.Core;
        if (core == null) return;

        // No exclusion filter here, unlike a selection click: a locked building is still a SURFACE
        // to drop a prop onto, even though it cannot itself be selected.
        // The base offset is applied here for the same reason End (GroundDropSelection) applies it:
        // the hit point is the SURFACE, and a prop whose pivot is not at its base would land half
        // sunk into it and then jump the first time the mapper pressed End.
        System.Numerics.Vector3 position;
        if (PickUnder(dip, null) is DinoEditor.Viewport.Picking.PickResult hit)
        {
            position = hit.HitPoint;
            position.Z = PlacementLogic.GroundDropPosition(hit.HitPoint.Z, ArchetypeBaseOffset(hash), 1f);
        }
        else
        {
            position = PlacementLogic.FallbackPlacePosition(core.Camera.Position, core.Camera.Forward);
        }

        var entity = _project.Place(hash, name, position, System.Numerics.Quaternion.Identity, 1f);
        _selection.Select(new DinoEditor.Viewport.Picking.SelectionTarget(
            DinoEditor.Viewport.Picking.SelectionKind.Project, entity.Id));
        _gizmo.Mode = DinoEditor.Viewport.Gizmo.GizmoMode.Translate;
    }

    /// <summary>Delete: removes the selected project entities. Vanilla placements and entities on
    /// locked layers are left alone - vanilla data is never mutated by this editor.</summary>
    private void DeleteSelection()
    {
        if (_project == null || _selection == null) return;

        var ids = EditableSelection();
        if (ids.Count == 0) return;

        _project.Delete(ids);
        _selection.Clear();
    }

    /// <summary>Ctrl+D: copies the selected project entities half a metre along X and Y and selects
    /// the copies, so the next drag moves the new ones.</summary>
    private void DuplicateSelection()
    {
        if (_project == null || _selection == null) return;

        var ids = EditableSelection();
        if (ids.Count == 0) return;

        var copies = _project.Duplicate(ids, new System.Numerics.Vector3(0.5f, 0.5f, 0f));
        if (copies.Count == 0) return;

        _selection.Clear();
        foreach (var copy in copies)
        {
            _selection.Add(new DinoEditor.Viewport.Picking.SelectionTarget(
                DinoEditor.Viewport.Picking.SelectionKind.Project, copy.Id));
        }
    }

    /// <summary>
    /// End: drops every selected project entity straight down onto whatever is under it. The ray
    /// starts a little ABOVE the entity so a prop already half sunk into the ground still finds it,
    /// and the whole selection is excluded from the pick so nothing lands on itself or on another
    /// entity that is falling with it. Entities over nothing are left where they are, and the whole
    /// group is one undo entry.
    /// </summary>
    private void GroundDropSelection()
    {
        var core = _session?.Core;
        if (core == null || _project == null || _undo == null || _selection == null) return;

        var ids = EditableSelection();
        if (ids.Count == 0) return;

        var falling = new HashSet<int>(ids);
        bool Excluded(DinoEditor.Viewport.Picking.SelectionTarget t) =>
            t.Kind == DinoEditor.Viewport.Picking.SelectionKind.Project && falling.Contains(t.Index);

        var moved = new List<(int id, System.Numerics.Vector3 pos, System.Numerics.Quaternion rot, float scale)>();
        foreach (int id in ids)
        {
            var entity = _project.Find(id);
            if (entity == null) continue;

            var origin = entity.Position + new System.Numerics.Vector3(0f, 0f, GroundDropRayLiftMetres);
            var ray = new DinoEditor.Viewport.Picking.Ray(origin, -System.Numerics.Vector3.UnitZ);
            if (core.PickRay(ray, Excluded) is not DinoEditor.Viewport.Picking.PickResult hit) continue;

            var position = entity.Position;
            position.Z = PlacementLogic.GroundDropPosition(
                hit.HitPoint.Z, ArchetypeBaseOffset(entity.ArchetypeHash), entity.Scale);
            if (position == entity.Position) continue;

            moved.Add((id, position, entity.Rotation, entity.Scale));
        }

        if (moved.Count == 0) return;
        _undo.Execute(_project.MakeTransformCommand(moved, "Drop to ground"));
    }

    /// <summary>The selected project entities that can actually be edited: vanilla placements are
    /// read-only and a locked layer is not editable.</summary>
    private List<int> EditableSelection()
    {
        var ids = new List<int>();
        if (_project == null || _selection == null) return ids;

        foreach (int id in _selection.ProjectIds)
        {
            if (!_project.IsLocked(id)) ids.Add(id);
        }

        return ids;
    }

    /// <summary>How far the archetype's pivot sits above its own base, in object space
    /// (<c>BbMin.Z</c>). Zero when the archetype is unknown here or its bounds are degenerate, which
    /// puts the pivot on the ground instead.</summary>
    private float ArchetypeBaseOffset(int archetypeHash)
    {
        var world = _session?.World;
        if (world == null || !world.ArchetypeSlotByHash.TryGetValue(archetypeHash, out int slot)) return 0f;
        if (slot < 0 || slot >= world.Archetypes.Count) return 0f;

        float min = world.Archetypes[slot].Record.BbMin.Z;
        return float.IsFinite(min) ? min : 0f;
    }

    /// <summary>F / the Focus button: frames the selected placement the same way the Content Drawer
    /// frames a go-to, at 2.5 bounding radii from a fixed three-quarter angle.</summary>
    private void FocusSelection()
    {
        var core = _session?.Core;
        if (core == null) return;
        if (!TryResolveSelection(out var position, out float radius)) return;

        float r = MathF.Max(radius, 1f);
        var dir = System.Numerics.Vector3.Normalize(new System.Numerics.Vector3(-1f, -1.2f, 0.8f));
        core.Camera.LookAt(position + dir * (r * 2.5f + 3f), position);
    }

    /// <summary>Where the primary selection is and how big it is, whichever store it lives in.
    /// False when nothing is selected or the target no longer exists (a deleted entity, or a
    /// placement index the current world does not have).</summary>
    private bool TryResolveSelection(out System.Numerics.Vector3 position, out float radius)
    {
        position = default;
        radius = 0f;
        if (_selection?.Primary is not DinoEditor.Viewport.Picking.SelectionTarget target) return false;

        if (target.Kind == DinoEditor.Viewport.Picking.SelectionKind.Project)
        {
            if (_project == null || !_project.Source.TryGet(target.Index, out var instance)) return false;
            position = instance.Position;
            radius = instance.Radius;
            return true;
        }

        var world = _session?.World;
        if (world == null || (uint)target.Index >= (uint)world.Placements.Length) return false;
        ref readonly var pl = ref world.Placements[target.Index];
        position = pl.Position;
        radius = pl.Radius;
        return true;
    }

    /// <summary>The display name of the primary selection, for the floating viewport label. A
    /// project entity shows the label the mapper gave it, falling back to its archetype name.</summary>
    private string PrimarySelectionName()
    {
        if (_selection?.Primary is not DinoEditor.Viewport.Picking.SelectionTarget target) return string.Empty;

        if (target.Kind == DinoEditor.Viewport.Picking.SelectionKind.Project)
        {
            var entity = _project?.Find(target.Index);
            if (entity == null) return string.Empty;
            if (!string.IsNullOrEmpty(entity.Name)) return entity.Name;
            if (!string.IsNullOrEmpty(entity.ArchetypeName)) return entity.ArchetypeName;
            return "0x" + entity.ArchetypeHash.ToString("X8");
        }

        var world = _session?.World;
        if (world == null || (uint)target.Index >= (uint)world.Placements.Length) return string.Empty;
        ref readonly var pl = ref world.Placements[target.Index];
        return SelectionName(pl.ArchetypeSlot, pl.ArchetypeHash);
    }

    /// <summary>Projects the selected placement to screen space and hands the overlay a label with
    /// its name and distance. Runs every frame (one matrix multiply), unlike the 4 Hz telemetry
    /// block: a label that lags the camera reads as a bug.</summary>
    private void UpdateSelectionLabel()
    {
        var core = _session?.Core;
        if (core == null || _host == null || !TryResolveSelection(out var target, out float targetRadius))
        {
            _overlayVm.UpdateSelection(null, 0, 0, false);
            return;
        }

        var size = _host.PixelSize;
        if (size.Width <= 0 || size.Height <= 0) { _overlayVm.UpdateSelection(null, 0, 0, false); return; }

        // The label floats over the top of the bounding sphere rather than the origin, so it does
        // not sit inside the object.
        var anchor = target + new System.Numerics.Vector3(0, 0, targetRadius);
        var clip = System.Numerics.Vector4.Transform(
            new System.Numerics.Vector4(anchor, 1f), core.LastViewProj);
        if (clip.W <= 0f) { _overlayVm.UpdateSelection(null, 0, 0, false); return; }

        float ndcX = clip.X / clip.W, ndcY = clip.Y / clip.W;
        // Big placements (a ground tile is over a hundred metres across) push the top-of-sphere
        // anchor off the top of the screen while the object itself fills the viewport, so the
        // anchor falls back to the centre and, failing that, is clamped to the edge. Only a
        // placement behind the camera (clip.W <= 0, handled above) hides the label.
        if (ndcX is < -1f or > 1f || ndcY is < -1f or > 1f)
        {
            var centreClip = System.Numerics.Vector4.Transform(
                new System.Numerics.Vector4(target, 1f), core.LastViewProj);
            if (centreClip.W > 0f)
            {
                float cx = centreClip.X / centreClip.W, cy = centreClip.Y / centreClip.W;
                if (cx is >= -1f and <= 1f && cy is >= -1f and <= 1f) { ndcX = cx; ndcY = cy; }
            }
            ndcX = Math.Clamp(ndcX, -0.98f, 0.98f);
            ndcY = Math.Clamp(ndcY, -0.98f, 0.98f);
        }

        double widthDip = Math.Max(1.0, _host.Bounds.Width);
        double heightDip = Math.Max(1.0, _host.Bounds.Height);
        double x = (ndcX + 1.0) / 2.0 * widthDip;
        double y = (1.0 - ndcY) / 2.0 * heightDip;
        // Keep the label's top-left corner inside the viewport. The label extends right and down
        // from here, so a wide label can still overhang the right edge - trimming that exactly would
        // need a measured text width, and 4 DIPs of inset is enough to stop the corner cases where
        // the anchor lands on or past the edge and the label draws half outside the view.
        x = Math.Clamp(x, 4.0, Math.Max(4.0, widthDip - 4.0));
        y = Math.Clamp(y, 4.0, Math.Max(4.0, heightDip - 4.0));

        string name = PrimarySelectionName();
        float distance = System.Numerics.Vector3.Distance(core.Camera.Position, target);
        _overlayVm.UpdateSelection(
            LocalizationService.Instance.Format("Selection.Label", name, distance), x, y, true);
    }

    /// <summary>The catalog's display name for an archetype slot, or the hash in hex when the slot
    /// has no catalog entry (an unnamed archetype).</summary>
    private string SelectionName(int slot, int hash)
    {
        var catalog = _session?.Catalog;
        if (catalog != null)
        {
            int i = catalog.IndexOfSlot(slot);
            if (i >= 0) return catalog.Entries[i].Name;
        }
        return "0x" + hash.ToString("X8");
    }

    /// <summary>Flies the camera to the placement of <paramref name="slot"/> nearest the current eye
    /// position, framed from a fixed three-quarter angle at 2.5 bounding radii.</summary>
    private void GoToNearestInstance(int slot)
    {
        var core = _session?.Core; var world = _session?.World;
        if (core == null || world == null) return;
        int p = world.Instances.Nearest(slot, core.Camera.Position, world.Placements);
        if (p < 0) { LogVm.Write(LocalizationService.Instance["Drawer.NoInstances"]); return; }
        ref readonly var pl = ref world.Placements[p];
        float r = MathF.Max(pl.Radius, 1f);
        var dir = System.Numerics.Vector3.Normalize(new System.Numerics.Vector3(-1f, -1.2f, 0.8f));
        core.Camera.LookAt(pl.Position + dir * (r * 2.5f + 3f), pl.Position);
    }

    /// <summary>Built once, on first use: <c>Region.YmapFiles[i]</c> to the <c>YmapRecord</c> that
    /// carries its entity extents, so the Outliner's Go To can frame a ymap without walking
    /// <c>Data.Ymaps</c> on every click.</summary>
    private Dictionary<string, DinoEditor.Formats.YmapRecord>? _ymapsByFile;

    /// <summary>Outliner "Go to": frames the camera on the centre of the ymap's entity extents, at a
    /// distance that scales with how big the ymap's footprint is.</summary>
    private void GoToYmap(int index)
    {
        var core = _session?.Core; var world = _session?.World; var data = _session?.Data;
        if (core == null || world == null || data == null) return;
        if ((uint)index >= (uint)world.YmapFiles.Length) return;

        _ymapsByFile ??= data.Ymaps.ToDictionary(y => y.File);
        if (!_ymapsByFile.TryGetValue(world.YmapFiles[index], out var ymap)) return;

        var centre = (ymap.EntMin + ymap.EntMax) / 2f;
        var span = ymap.EntMax - ymap.EntMin;
        float radius = MathF.Max(MathF.Max(span.X, span.Y) * 0.6f, 30f);
        var dir = System.Numerics.Vector3.Normalize(new System.Numerics.Vector3(-1f, -1.2f, 0.8f));
        core.Camera.LookAt(centre + dir * radius, centre);
    }
}

