using System.Globalization;
using Avalonia.Data.Converters;

namespace DinoEditor.App.Converters;

/// <summary>Formats an archetype name hash as <c>0x________</c>. The catalog stores the hash as a
/// signed int because that is how the game files carry it; the display is unsigned, which is the
/// form every GTA tool and every wiki page uses.</summary>
public sealed class HashToHexConverter : IValueConverter
{
    public object Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
        => value is int hash ? "0x" + unchecked((uint)hash).ToString("x8", CultureInfo.InvariantCulture) : string.Empty;

    public object ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture) =>
        throw new NotSupportedException();
}

