using System.Globalization;
using Avalonia.Data.Converters;

namespace DinoEditor.App.Converters;

/// <summary>Compares a bound value's string form against the converter parameter. Used by
/// DockTheme.axaml to switch a setter on one specific dock id, which a style selector cannot do on
/// its own - selectors match control state, not the data behind the control.</summary>
public sealed class StringEqualsConverter : IValueConverter
{
    /// <summary>When true the converter returns the negation, so one converter serves both
    /// "is this dock" and "is this not that dock".</summary>
    public bool Invert { get; set; }

    public object Convert(object? value, Type targetType, object? parameter, CultureInfo culture)
    {
        bool equal = string.Equals(value?.ToString(), parameter?.ToString(), StringComparison.Ordinal);
        return Invert ? !equal : equal;
    }

    public object ConvertBack(object? value, Type targetType, object? parameter, CultureInfo culture) =>
        throw new NotSupportedException();
}

