using Avalonia.Controls;
using DinoEditor.App.Services;
using Dock.Model.Controls;
using Dock.Model.Core;
using Dock.Model.Mvvm;
using Dock.Model.Mvvm.Controls;

namespace DinoEditor.App.Docks;

/// <summary>
/// The shell layout, copied from Unreal Engine 5 (design/ue5-ref-1.png, design/ue5-ref-2.png):
/// the Viewport document takes the centre and most of the width, Outliner sits over Details in a
/// narrow right column, and a Content Drawer / Output Log drawer runs across the bottom and
/// collapses to nothing from the status bar, the way UE's Content Drawer does.
///
/// The viewport control is handed in rather than created by a data template, so floating and
/// re-docking reparent the same control and the D3D resources survive - measured at 0 frames lost
/// in the bake-off (docs/shell-bakeoff/README.md).
/// </summary>
public sealed class DockFactory : Factory
{
    private readonly Control _viewportView;
    private readonly AppSettings _settings;

    public DockFactory(Control viewportView, AppSettings settings)
    {
        _viewportView = viewportView;
        _settings = settings;
        _isDrawerVisible = settings.DrawerVisible;
    }

    public ViewportDocument ViewportDoc { get; private set; } = null!;
    public DocumentDock DocumentDock { get; private set; } = null!;
    public IRootDock RootDock { get; private set; } = null!;

    public OutlinerTool Outliner { get; private set; } = null!;
    public DetailsTool Details { get; private set; } = null!;
    public ContentDrawerTool ContentDrawer { get; private set; } = null!;
    public OutputLogTool OutputLog { get; private set; } = null!;

    /// <summary>The bottom drawer's tool dock; the status bar drives it through
    /// <see cref="ShowDrawerTool"/> and <see cref="IsDrawerVisible"/>.</summary>
    public ToolDock DrawerDock { get; private set; } = null!;

    private ToolDock _outlinerPane = null!;
    private ToolDock _detailsPane = null!;
    private ProportionalDock _rightColumn = null!;
    private ProportionalDock _centreColumn = null!;
    private ProportionalDockSplitter _drawerSplitter = null!;

    private bool _isDrawerVisible;

    /// <summary>Raised whenever the drawer opens, closes or changes tab, so the status bar toggles
    /// can show which one is active the way Unreal highlights the open drawer.</summary>
    public event EventHandler? DrawerStateChanged;

    /// <summary>The id of the drawer tool currently showing, or null while the drawer is closed.</summary>
    public string? ActiveDrawerToolId =>
        IsDrawerVisible ? DrawerDock.ActiveDockable?.Id : null;

    /// <summary>UE's Content Drawer is a drawer, not a panel: closing it gives the whole row back to
    /// the viewport rather than leaving an empty strip. Removing the dock and its splitter from the
    /// centre column is the only collapse Dock.Avalonia models reliably, so that is what this does;
    /// the drawer's own proportion is untouched and comes back on reopen.</summary>
    public bool IsDrawerVisible
    {
        get => _isDrawerVisible;
        set
        {
            if (SetDrawerVisible(value)) DrawerStateChanged?.Invoke(this, EventArgs.Empty);
        }
    }

    /// <summary>Applies the new visibility and reports whether anything moved, WITHOUT raising.
    /// ShowDrawerTool can change the tab and the visibility in one go and must announce that once,
    /// not twice.</summary>
    private bool SetDrawerVisible(bool value)
    {
        if (_isDrawerVisible == value) return false;
        _isDrawerVisible = value;
        ApplyDrawerVisibility();
        return true;
    }

    public override IRootDock CreateLayout()
    {
        var loc = LocalizationService.Instance;

        ViewportDoc = new ViewportDocument
        {
            Id = "Viewport",
            Title = loc["Dock.Viewport"],
            View = _viewportView,
            CanClose = false,
            CanFloat = true,
        };

        DocumentDock = new DocumentDock
        {
            Id = "Documents",
            Title = "Documents", // layout node
            IsCollapsable = false,
            CanCreateDocument = false,
            VisibleDockables = CreateList<IDockable>(ViewportDoc),
            ActiveDockable = ViewportDoc,
            Proportion = 1.0 - _settings.BottomPaneProportion,
        };

        Outliner = new OutlinerTool { Id = "Outliner", Title = loc["Dock.Outliner"], CanClose = false };
        Details = new DetailsTool { Id = "Details", Title = loc["Dock.Details"], CanClose = false };
        // The drawer is opened and closed from the status bar only. Dock's own chrome (pin, close,
        // float) would collapse or move the dock without going through IsDrawerVisible, leaving the
        // flag out of step with the tree - so those capabilities are off and the chrome buttons
        // disappear with them.
        ContentDrawer = new ContentDrawerTool
        {
            Id = "ContentDrawer",
            Title = loc["Dock.ContentDrawer"],
            CanClose = false,
            CanPin = false,
            CanFloat = false,
        };
        OutputLog = new OutputLogTool
        {
            Id = "OutputLog",
            Title = loc["Dock.OutputLog"],
            CanClose = false,
            CanPin = false,
            CanFloat = false,
        };

        _outlinerPane = new ToolDock
        {
            Id = "OutlinerPane",
            Title = "OutlinerPane", // layout node
            Proportion = _settings.OutlinerProportion,
            Alignment = Alignment.Right,
            VisibleDockables = CreateList<IDockable>(Outliner),
            ActiveDockable = Outliner,
        };

        _detailsPane = new ToolDock
        {
            Id = "DetailsPane",
            Title = "DetailsPane", // layout node
            Proportion = 1.0 - _settings.OutlinerProportion,
            Alignment = Alignment.Right,
            VisibleDockables = CreateList<IDockable>(Details),
            ActiveDockable = Details,
        };

        _rightColumn = new ProportionalDock
        {
            Id = "RightColumn",
            Title = "RightColumn", // layout node
            Orientation = Orientation.Vertical,
            Proportion = _settings.RightPaneProportion,
            VisibleDockables = CreateList<IDockable>(
                _outlinerPane,
                new ProportionalDockSplitter(),
                _detailsPane),
            ActiveDockable = _outlinerPane,
        };

        DrawerDock = new ToolDock
        {
            Id = "DrawerPane",
            Title = "DrawerPane", // layout node
            Proportion = _settings.BottomPaneProportion,
            Alignment = Alignment.Bottom,
            VisibleDockables = CreateList<IDockable>(ContentDrawer, OutputLog),
            ActiveDockable = ContentDrawer,
        };

        _drawerSplitter = new ProportionalDockSplitter();

        _centreColumn = new ProportionalDock
        {
            Id = "CentreColumn",
            Title = "CentreColumn", // layout node
            Orientation = Orientation.Vertical,
            Proportion = 1.0 - _settings.RightPaneProportion,
            VisibleDockables = CreateList<IDockable>(
                DocumentDock,
                _drawerSplitter,
                DrawerDock),
            ActiveDockable = DocumentDock,
        };

        var main = new ProportionalDock
        {
            Id = "MainLayout",
            Title = "MainLayout", // layout node
            Orientation = Orientation.Horizontal,
            VisibleDockables = CreateList<IDockable>(
                _centreColumn,
                new ProportionalDockSplitter(),
                _rightColumn),
            ActiveDockable = _centreColumn,
        };

        var root = CreateRootDock();
        root.Id = "Root";
        root.Title = "Root"; // layout node
        root.IsCollapsable = false;
        root.VisibleDockables = CreateList<IDockable>(main);
        root.ActiveDockable = main;
        root.DefaultDockable = main;
        RootDock = root;

        if (!_isDrawerVisible) ApplyDrawerVisibility();

        return root;
    }

    public override void InitLayout(IDockable layout)
    {
        ContextLocator = new Dictionary<string, Func<object?>>();
        DockableLocator = new Dictionary<string, Func<IDockable?>>
        {
            ["Viewport"] = () => ViewportDoc,
            ["Outliner"] = () => Outliner,
            ["Details"] = () => Details,
            ["ContentDrawer"] = () => ContentDrawer,
            ["OutputLog"] = () => OutputLog,
        };
        HostWindowLocator = new Dictionary<string, Func<IHostWindow?>>
        {
            [nameof(IDockWindow)] = () => new Dock.Avalonia.Controls.HostWindow(),
        };
        DefaultHostWindowLocator = () => new Dock.Avalonia.Controls.HostWindow();
        base.InitLayout(layout);
    }

    /// <summary>Opens the drawer on <paramref name="toolId"/>, or closes it when that tab is already
    /// the visible one - the same click-to-toggle the UE status bar buttons have.</summary>
    public void ShowDrawerTool(string toolId)
    {
        var tool = (DrawerDock.VisibleDockables ?? new List<IDockable>())
            .FirstOrDefault(d => d.Id == toolId);
        if (tool == null) return;

        // Believe the tree, not the flag. Anything that moved the drawer without going through
        // IsDrawerVisible would otherwise cost the user two clicks to get it back.
        SyncDrawerFlag();

        if (_isDrawerVisible && ReferenceEquals(DrawerDock.ActiveDockable, tool))
        {
            if (SetDrawerVisible(false)) DrawerStateChanged?.Invoke(this, EventArgs.Empty);
            return;
        }

        // One announcement per click, whether this switched the tab, opened the drawer, or both.
        bool changed = !ReferenceEquals(DrawerDock.ActiveDockable, tool);
        DrawerDock.ActiveDockable = tool;
        changed |= SetDrawerVisible(true);
        if (changed) DrawerStateChanged?.Invoke(this, EventArgs.Empty);
    }

    /// <summary>Brings the cached flag back in line with what is actually in the centre column.</summary>
    private void SyncDrawerFlag() =>
        _isDrawerVisible = _centreColumn.VisibleDockables?.Contains(DrawerDock) == true;

    /// <summary>Persisting the whole Dock tree would mean serialising the live viewport Control, so
    /// only the three proportions the user actually drags are saved, plus whether the drawer is
    /// open. Which panels exist is fixed by the product, not by the user, in Drop 1.</summary>
    public void SaveProportions(AppSettings settings)
    {
        if (IsSane(_rightColumn.Proportion)) settings.RightPaneProportion = _rightColumn.Proportion;
        if (IsSane(DrawerDock.Proportion)) settings.BottomPaneProportion = DrawerDock.Proportion;
        if (IsSane(_outlinerPane.Proportion)) settings.OutlinerProportion = _outlinerPane.Proportion;
        settings.DrawerVisible = IsDrawerVisible;
    }

    /// <summary>Re-titles every dockable after a live language switch.</summary>
    public void RefreshTitles()
    {
        var loc = LocalizationService.Instance;
        ViewportDoc.Title = loc["Dock.Viewport"];
        Outliner.Title = loc["Dock.Outliner"];
        Details.Title = loc["Dock.Details"];
        ContentDrawer.Title = loc["Dock.ContentDrawer"];
        OutputLog.Title = loc["Dock.OutputLog"];
    }

    /// <summary>A collapsed or maximised pane must not be persisted as the new normal, or the next
    /// start opens with an invisible panel and no way back short of deleting settings.json.</summary>
    private static bool IsSane(double proportion) => proportion is > 0.02 and < 0.9;

    private void ApplyDrawerVisibility()
    {
        var children = _centreColumn.VisibleDockables;
        if (children == null) return;

        if (_isDrawerVisible)
        {
            if (children.Contains(DrawerDock)) return;
            children.Add(_drawerSplitter);
            children.Add(DrawerDock);
            DocumentDock.Proportion = 1.0 - DrawerDock.Proportion;
        }
        else
        {
            children.Remove(DrawerDock);
            children.Remove(_drawerSplitter);
            DocumentDock.Proportion = 1.0;
        }

        _centreColumn.ActiveDockable = DocumentDock;
    }
}

