using System.Diagnostics;
using Avalonia.Controls;
using DinoEditor.App.Input;
using DinoEditor.App.Services;
using DinoEditor.App.Services.Thumbnails;
using DinoEditor.Viewport;
using DinoEditor.Viewport.Catalog;
using DinoEditor.Viewport.Bench;

namespace DinoEditor.App.Flight;

/// <summary>
/// The Phase 0b flight, run inside the product shell so the App is measured on the same numbers as
/// StreamSpike and the bake-off: 3 s prime, then t = 0..60 s of the downtown FlightPath, one
/// FrameSample per frame, screenshots at fixed times, summary written to docs/app-drop1/.
///
/// It drives the camera through RenderLoop.BeforeUpdate rather than owning a loop of its own, so
/// what is measured is exactly the loop the user gets.
/// </summary>
public sealed class AppFlight
{
    private const float PrimeSeconds = 3f;
    private static readonly float[] ShotTimes = { 4f, 14f, 23f, 32f, 44f, 56f };

    /// <summary>Flight time at which --bake-thumbs fires its burst of requests.</summary>
    private const float ThumbRequestTime = 2f;

    private readonly RenderLoop _loop;
    private readonly GameSession _session;
    private readonly EditorCameraController _camera;
    private readonly Window _window;
    private readonly ILogSink _log;
    private readonly string _outDir;
    private readonly ThumbnailService? _thumbs;
    private readonly Func<ArchetypeCatalog?> _catalog;
    private readonly int _bakeThumbs;
    private readonly Func<int> _projectEntities;

    private readonly FrameLog _frameLog = new();
    private readonly List<FrameSample> _samples = new();
    private readonly GcProbe _gc = new();
    private readonly bool[] _shotTaken = new bool[ShotTimes.Length];

    private FlightPath? _flight;
    private double _primeClock, _flightClock;
    private bool _priming = true, _finished;
    private int _frameIndex;
    private long _peakVram;
    private double _startupSeconds;
    private readonly Stopwatch _startup = Stopwatch.StartNew();

    /// <summary>The app's own pre-update hook, chained by <see cref="Attach"/> and restored by
    /// <see cref="Finish"/>.</summary>
    private Action<float>? _previousBeforeUpdate;

    private bool _thumbsRequested;
    private int _thumbsRequestedCount;
    private int _baseBaked, _baseDiskHits, _baseFailed;

    public AppFlight(RenderLoop loop, GameSession session, EditorCameraController camera,
        Window window, ILogSink log, string outDir,
        ThumbnailService? thumbs = null, Func<ArchetypeCatalog?>? catalog = null, int bakeThumbs = 0,
        Func<int>? projectEntities = null)
    {
        _loop = loop;
        _session = session;
        _camera = camera;
        _window = window;
        _log = log;
        _outDir = outDir;
        _thumbs = thumbs;
        _catalog = catalog ?? (() => null);
        _bakeThumbs = bakeThumbs;
        // How much of the mapper's own work the flight was carrying. Read at the END of the run:
        // --place-demo puts its entities in two seconds in, after the flight has already attached.
        _projectEntities = projectEntities ?? (() => 0);
    }

    public event Action? Finished;

    /// <summary>
    /// Takes over the loop's pre-update hook for the duration of the flight. The hook the app
    /// already installed is CHAINED, not replaced: it is what hands the gizmo state to the core
    /// every frame, and dropping it would leave a --place-demo flight drawing no gizmo for the rest
    /// of the process. <see cref="Finish"/> puts the original back.
    /// </summary>
    public void Attach()
    {
        _previousBeforeUpdate = _loop.BeforeUpdate;
        _loop.BeforeUpdate = dt =>
        {
            _previousBeforeUpdate?.Invoke(dt);
            Step(dt);
        };
    }

    private void Step(float dt)
    {
        if (_finished) return;
        var core = _session.Core;
        if (core == null) return;

        var flight = _flight;
        if (flight == null)
        {
            flight = _flight = new FlightPath(_session.StartCentre, _session.StartGroundZ);
            _startupSeconds = _startup.Elapsed.TotalSeconds;
            _gc.Reset();
            _log.Write($"[flight] startup to first frame {_startupSeconds:F2}s; flight {flight.Duration:F0}s over downtown");
        }

        float t;
        if (_priming)
        {
            _primeClock += dt;
            t = 0f;
            if (_primeClock >= PrimeSeconds)
            {
                _priming = false;
                _log.Write($"[flight] prime done ({core.Cache.ResidentCount} archetypes resident, " +
                           $"{VramTracker.Bytes / 1048576.0:F0} MB). Flight starts.");
            }
        }
        else
        {
            _flightClock += dt;
            t = (float)_flightClock;
        }

        // The flight owns the camera for the duration; the controller is idle.
        _camera.ClearKeys();
        var (pos, yaw, pitch) = flight.Evaluate(t);
        core.Camera.Position = pos;
        core.Camera.Yaw = yaw;
        core.Camera.Pitch = pitch;

        _gc.Sample();
        _peakVram = Math.Max(_peakVram, VramTracker.Bytes);

        if (_priming) { _frameIndex++; return; }

        if (!_thumbsRequested && _bakeThumbs > 0 && t >= ThumbRequestTime) RequestThumbnails();

        bool shotThisFrame = false;
        for (int i = 0; i < ShotTimes.Length; i++)
            if (!_shotTaken[i] && t >= ShotTimes[i])
            {
                _shotTaken[i] = true;
                shotThisFrame = true;
                TakeShot($"shot-{ShotTimes[i]:F0}", t);
            }

        var s = new FrameSample
        {
            Frame = _frameIndex,
            TimeSeconds = t,
            FrameMs = dt * 1000.0,
            UploadHitchMs = core.Cache.LastUploadMs,
            ResidentArchetypes = core.Cache.ResidentCount,
            InFlight = core.Cache.InFlightCount,
            VramBytes = VramTracker.Bytes,
            GeomBytes = core.Cache.GeometryBytes,
            TexBytes = core.Cache.TextureBytes,
            DrawCalls = core.Renderer.LastDrawCalls,
            Instances = core.Renderer.LastInstances,
            Triangles = core.Renderer.LastTriangles,
            NeededCells = core.Grid.NeededCells,
            VisibleCells = core.Grid.VisibleCells,
            DrawnEntities = core.Grid.DrawnEntities,
            ByLodLevel = (int[])core.Grid.DrawnByLodLevel.Clone(),
            ByDrawableLod = (int[])core.Grid.DrawnByDrawableLod.Clone(),
            CamX = pos.X, CamY = pos.Y, CamZ = pos.Z,
            ScreenshotFrame = shotThisFrame,
            Gc0 = _gc.D0, Gc1 = _gc.D1, Gc2 = _gc.D2,
            GcPauseMs = _gc.PauseMs,
            LastGcPauseMs = _gc.LastGcPauseMs,
            LastGcGeneration = _gc.NewGcThisFrame ? _gc.LastGcGeneration : -1,
            AllocBytes = _gc.AllocBytes,
            RenderAllocBytes = _gc.ThreadAllocBytes,
            GridUpdateMs = core.LastGridUpdateMs,
            CacheUpdateMs = core.LastCacheUpdateMs,
            BuildBatchesMs = core.LastBuildBatchesMs,
            DrawMs = core.LastDrawMs,
            // One frame behind by construction: BeforeUpdate runs before this frame's AfterRender,
            // so this is the previous frame's thumbnail tick. Over a 60 s series that shift does
            // not move the percentile.
            AfterRenderMs = _loop.LastAfterRenderMs,
        };
        _frameLog.Add(s);
        _samples.Add(s);

        _frameIndex++;
        if (t >= flight.Duration) Finish();
    }

    /// <summary>The --bake-thumbs load: the N most-placed archetypes, requested in one burst. That
    /// is the worst realistic case for the drawer - a user scrolling the most common props while
    /// the camera keeps flying - and it is what the flight is meant to price.</summary>
    private void RequestThumbnails()
    {
        _thumbsRequested = true;
        var thumbs = _thumbs;
        var catalog = _catalog();
        if (thumbs == null || catalog == null)
        {
            _log.Write("[thumbs] --bake-thumbs requested but no thumbnail service or catalog; skipped");
            return;
        }

        _baseBaked = thumbs.BakedCount;
        _baseDiskHits = thumbs.DiskHits;
        _baseFailed = thumbs.FailedCount;

        var picks = catalog.Entries
            .OrderByDescending(e => e.InstanceCount)
            .Take(_bakeThumbs)
            .ToArray();
        foreach (var e in picks) thumbs.Request(e.NameHash, e.Slot, _ => { });
        _thumbsRequestedCount = picks.Length;
        _log.Write($"[thumbs] requested {picks.Length} thumbnails at t={ThumbRequestTime:F0}s " +
                   $"(catalog {catalog.Count}, baseline baked={_baseBaked} disk={_baseDiskHits})");
    }

    private void TakeShot(string name, float t)
    {
        try
        {
            string path = Path.Combine(_outDir, name + ".png");
            WindowCapture.Capture(_window.TryGetPlatformHandle()?.Handle ?? IntPtr.Zero, path);
            _log.Write($"[shot] {path} at t={t:F1}s");
        }
        catch (Exception ex)
        {
            _log.Write("[shot] failed: " + ex.Message);
        }
    }

    private void Finish()
    {
        if (_finished) return;
        _finished = true;
        _loop.BeforeUpdate = _previousBeforeUpdate;
        WriteResults();
        _log.Write("=== Flight complete ===");
        Finished?.Invoke();
    }

    private void WriteResults()
    {
        Directory.CreateDirectory(_outDir);
        _frameLog.WriteCsv(Path.Combine(_outDir, "run-log.csv"));

        var proc = Process.GetCurrentProcess();
        proc.Refresh();
        var world = _session.World!;

        var lines = new List<string>
        {
            "host_technique=Avalonia composition GPU interop (DinoEditor.App)",
            "avalonia_version=12.1.1",
            "dock_version=12.1.0.4",
            $"startup_to_first_frame_seconds={_startupSeconds:F2}",
            $"world_ymaps={world.YmapCount}",
            $"world_entities={world.EntityCount}",
            $"world_active_entities={world.ActiveCount}",
            $"world_archetypes={world.Archetypes.Count}",
            $"project_entities={_projectEntities()}",
            $"grid_cells={_session.Core!.Grid.Cells.Count}",
            $"frames={_samples.Count}",
            $"p50_ms={_frameLog.Percentile(0.50):F3}",
            $"p95_ms={_frameLog.Percentile(0.95):F3}",
            $"p99_ms={_frameLog.Percentile(0.99):F3}",
            $"max_ms={_frameLog.Percentile(1):F3}",
            $"mean_ms={_frameLog.MeanMs:F3}",
            $"grid_update_p50_ms={_frameLog.Percentile(s => s.GridUpdateMs, 0.50):F4}",
            $"grid_update_p95_ms={_frameLog.Percentile(s => s.GridUpdateMs, 0.95):F4}",
            $"cache_update_p50_ms={_frameLog.Percentile(s => s.CacheUpdateMs, 0.50):F4}",
            $"cache_update_p95_ms={_frameLog.Percentile(s => s.CacheUpdateMs, 0.95):F4}",
            $"build_batches_p50_ms={_frameLog.Percentile(s => s.BuildBatchesMs, 0.50):F4}",
            $"build_batches_p95_ms={_frameLog.Percentile(s => s.BuildBatchesMs, 0.95):F4}",
            $"draw_p50_ms={_frameLog.Percentile(s => s.DrawMs, 0.50):F4}",
            $"draw_p95_ms={_frameLog.Percentile(s => s.DrawMs, 0.95):F4}",
            $"after_render_p50_ms={_frameLog.Percentile(s => s.AfterRenderMs, 0.50):F4}",
            $"thumb_tick_p95_ms={_frameLog.Percentile(s => s.AfterRenderMs, 0.95):F4}",
            $"thumb_tick_max_ms={_frameLog.Percentile(s => s.AfterRenderMs, 1):F4}",
            $"thumbs_requested={_thumbsRequestedCount}",
            $"thumbs_baked={(_thumbs?.BakedCount ?? 0) - _baseBaked}",
            $"thumbs_disk_hits={(_thumbs?.DiskHits ?? 0) - _baseDiskHits}",
            $"thumbs_failed={(_thumbs?.FailedCount ?? 0) - _baseFailed}",
            $"thumbs_remaining_at_end={(_thumbs?.QueueDepth ?? 0) + (_thumbs?.InFlight ?? 0)}",
            $"max_hitch_ms={_frameLog.MaxHitch:F3}",
            $"hitch_p95_ms={_frameLog.HitchPercentile(0.95):F3}",
            $"hitch_p99_ms={_frameLog.HitchPercentile(0.99):F3}",
            $"frames_over_4ms_hitch={_frameLog.FramesOverHitch(4.0)}",
            $"peak_vram_mb={_peakVram / 1048576.0:F1}",
            $"peak_draw_calls={_frameLog.PeakDrawCalls}",
            $"peak_triangles={_frameLog.PeakTriangles}",
            $"peak_drawn_entities={_frameLog.PeakDrawn}",
            $"peak_resident_archetypes={_frameLog.PeakResident}",
            $"gc_gen0={_frameLog.TotalGen0}",
            $"gc_gen1={_frameLog.TotalGen1}",
            $"gc_gen2={_frameLog.TotalGen2}",
            $"gc_worst_single_pause_ms={_frameLog.MaxSingleGcPauseMs:F1}",
            $"alloc_mb_per_second={_frameLog.AllocBytesPerSecond / 1048576.0:F2}",
            $"render_alloc_bytes_per_frame={_frameLog.MeanRenderAllocBytes:F0}",
            $"private_bytes_end_mb={proc.PrivateMemorySize64 / 1048576.0:F1}",
            $"working_set_end_mb={proc.WorkingSet64 / 1048576.0:F1}",
            "",
            "# budgets (Phase 0b)",
            $"budget_p95_ms=16.6 -> {(_frameLog.Percentile(0.95) < 16.6 ? "GO" : "NO-GO")}",
            $"budget_hitch_ms=4 -> {(_frameLog.MaxHitch < 4.0 ? "GO" : "NO-GO")}",
            $"budget_vram_mb=1024 -> {(_peakVram / 1048576.0 < 1024 ? "GO" : "NO-GO")}",
        };
        File.WriteAllLines(Path.Combine(_outDir, "summary.txt"), lines);
        foreach (var l in lines) _log.Write("  " + l);
        _log.Write($"Wrote {_outDir}\\summary.txt and run-log.csv");
    }
}

