using System.Runtime.InteropServices;

namespace DinoEditor.App.Flight;

/// <summary>Whole-window capture for the flight screenshots. PrintWindow with
/// PW_RENDERFULLCONTENT captures DirectComposition content, which is what the composition viewport
/// is; the BitBlt path is the fallback. Copied from the bake-off harness Win32.CaptureWindow.</summary>
public static class WindowCapture
{
    private const uint PW_RENDERFULLCONTENT = 0x00000002;
    private const int SRCCOPY = 0x00CC0020;

    [StructLayout(LayoutKind.Sequential)]
    private struct RECT { public int Left, Top, Right, Bottom; }

    [DllImport("user32.dll")] private static extern bool GetWindowRect(IntPtr hWnd, out RECT rect);
    [DllImport("user32.dll")] private static extern bool PrintWindow(IntPtr hWnd, IntPtr hdcBlt, uint flags);
    [DllImport("user32.dll")] private static extern IntPtr GetDC(IntPtr hWnd);
    [DllImport("user32.dll")] private static extern int ReleaseDC(IntPtr hWnd, IntPtr hdc);
    [DllImport("gdi32.dll")] private static extern bool BitBlt(IntPtr dest, int x, int y, int cx, int cy, IntPtr src, int sx, int sy, int rop);

    public static void Capture(IntPtr hwnd, string path)
    {
        if (!GetWindowRect(hwnd, out var r)) throw new InvalidOperationException("GetWindowRect failed");
        int w = Math.Max(1, r.Right - r.Left);
        int h = Math.Max(1, r.Bottom - r.Top);
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        using var bmp = new System.Drawing.Bitmap(w, h, System.Drawing.Imaging.PixelFormat.Format32bppArgb);
        using (var g = System.Drawing.Graphics.FromImage(bmp))
        {
            IntPtr hdc = g.GetHdc();
            try
            {
                if (!PrintWindow(hwnd, hdc, PW_RENDERFULLCONTENT))
                {
                    IntPtr src = GetDC(hwnd);
                    try { BitBlt(hdc, 0, 0, w, h, src, 0, 0, SRCCOPY); }
                    finally { ReleaseDC(hwnd, src); }
                }
            }
            finally { g.ReleaseHdc(hdc); }
        }
        bmp.Save(path, System.Drawing.Imaging.ImageFormat.Png);
    }
}

