using Avalonia;
using Avalonia.Controls;
using Avalonia.Platform;
using Avalonia.Rendering.Composition;
using Avalonia.VisualTree;
using Vortice.Direct3D;
using Vortice.Direct3D11;
using Vortice.DXGI;

namespace DinoEditor.App.Hosting;

/// <summary>
/// Hosting mode (b): no child HWND at all. We render into our own shared D3D11 texture and hand it
/// to Avalonia's compositor through ICompositionGpuInterop, so the viewport becomes a normal
/// composition visual inside Avalonia's own scene graph - which is what lets Avalonia elements be
/// layered on top of it. Adapted from the MIT-licensed AvaloniaUI/Avalonia samples/GpuInterop
/// sample (D3DDemo/D3D11DemoControl.cs, D3D11Swapchain.cs, DrawingSurfaceDemoBase.cs,
/// src/Avalonia.Base/Rendering/SwapchainBase.cs).
/// </summary>
public sealed class CompositionViewportHost : Control, IDisposable
{
    // Copied verbatim from src/ShellBakeoff.Avalonia/Hosting/CompositionViewportHost.cs, the
    // Phase 1a bake-off winner. Technique: render into our own shared D3D11 texture
    // (B8G8R8A8_UNorm, SharedKeyedMutex | SharedNTHandle), import it into Avalonia's compositor
    // through ICompositionGpuInterop as D3D11TextureNtHandle, and publish it per frame with
    // UpdateWithKeyedMutexAsync. The CompositionSurfaceVisual is mirrored Scale(1,-1,1) because
    // the compositor samples the imported texture bottom-up. Do not "simplify" any of this
    // without re-running docs/shell-bakeoff.
    private readonly Action<string> _log;

    private Compositor? _compositor;
    private CompositionDrawingSurface? _surface;
    private CompositionSurfaceVisual? _visual;
    private ICompositionGpuInterop? _interop;
    private string? _handleType;

    private ID3D11Device? _device;
    private ID3D11DeviceContext? _context;
    private readonly List<SharedImage> _pool = new();
    private SharedImage? _current;

    private ID3D11Texture2D? _depthTex;
    private ID3D11DepthStencilView? _dsv;
    private int _depthW, _depthH;

    private bool _initStarted;
    private bool _disposed;

    public CompositionViewportHost(Action<string> log)
    {
        _log = log;
        Focusable = false;
    }

    public string Info { get; private set; } = "";
    public int DeviceGeneration { get; private set; }
    public ID3D11Device Device => _device!;
    public ID3D11DeviceContext Context => _context!;
    public bool IsReady => !_disposed && _device != null && _interop != null && _surface != null && PixelSize.Width > 0;

    /// <summary>Set when the compositor reports no GPU interop at all - the caller fails loudly.</summary>
    public string? FatalError { get; private set; }

    public PixelSize PixelSize
    {
        get
        {
            var top = TopLevel.GetTopLevel(this);
            double scale = top?.RenderScaling ?? 1.0;
            int w = Math.Max(0, (int)Math.Round(Bounds.Width * scale));
            int h = Math.Max(0, (int)Math.Round(Bounds.Height * scale));
            return new PixelSize(w, h);
        }
    }

    protected override void OnAttachedToVisualTree(VisualTreeAttachmentEventArgs e)
    {
        base.OnAttachedToVisualTree(e);
        Initialize();
    }

    private async void Initialize()
    {
        if (_initStarted) return;
        _initStarted = true;
        try
        {
            var selfVisual = ElementComposition.GetElementVisual(this)!;
            _compositor = selfVisual.Compositor;
            _surface = _compositor.CreateDrawingSurface();
            _visual = _compositor.CreateSurfaceVisual();
            _visual.Size = new Vector(Bounds.Width, Bounds.Height);
            _visual.Surface = _surface;
            ElementComposition.SetElementChildVisual(this, _visual);

            _interop = await _compositor.TryGetCompositionGpuInterop();
            if (_interop == null)
            {
                FatalError = "Compositor reported NO GPU interop for the current backend (software fallback?).";
                _log("[composition] " + FatalError);
                return;
            }

            var supported = _interop.SupportedImageHandleTypes?.ToArray() ?? Array.Empty<string>();
            _log($"[composition] ICompositionGpuInterop.SupportedImageHandleTypes = [{string.Join(", ", supported)}]");
            _log($"[composition] interop device LUID={_interop.DeviceLuid?.Length ?? 0}B UUID={_interop.DeviceUuid?.Length ?? 0}B");

            if (supported.Contains(KnownPlatformGraphicsExternalImageHandleTypes.D3D11TextureNtHandle))
                _handleType = KnownPlatformGraphicsExternalImageHandleTypes.D3D11TextureNtHandle;
            else if (supported.Contains(KnownPlatformGraphicsExternalImageHandleTypes.D3D11TextureGlobalSharedHandle))
                _handleType = KnownPlatformGraphicsExternalImageHandleTypes.D3D11TextureGlobalSharedHandle;
            else
            {
                FatalError = $"No D3D11 shared-texture handle type accepted by the compositor: [{string.Join(", ", supported)}]";
                _log("[composition] " + FatalError);
                return;
            }

            CreateDevice();
            _log($"[composition] {Info}");
        }
        catch (Exception ex)
        {
            FatalError = ex.ToString();
            _log("[composition] init FAILED: " + ex);
        }
    }

    // ---------------------------------------------------------------- device

    private void CreateDevice()
    {
        FeatureLevel[] levels = { FeatureLevel.Level_11_0 };
        D3D11.D3D11CreateDevice(null, DriverType.Hardware, DeviceCreationFlags.BgraSupport, levels,
            out var device, out _, out var context);
        _device = device!;
        _context = context!;
        DeviceGeneration++;
        using var dxgiDevice = _device.QueryInterface<IDXGIDevice>();
        using var adapter = dxgiDevice.GetAdapter();
        Info = $"composition GPU interop, handle type {_handleType}, on {adapter.Description.Description.Trim()}";
    }

    public void RecreateDevice()
    {
        FreeGpuResources();
        _context?.Dispose(); _context = null;
        _device?.Dispose(); _device = null;
        CreateDevice();
    }

    private void FreeGpuResources()
    {
        foreach (var img in _pool) img.Dispose();
        _pool.Clear();
        _current = null;
        _dsv?.Dispose(); _dsv = null;
        _depthTex?.Dispose(); _depthTex = null;
        _depthW = _depthH = 0;
    }

    // ---------------------------------------------------------------- frame

    public bool BeginFrame(out ID3D11RenderTargetView rtv, out ID3D11DepthStencilView dsv, out int width, out int height)
    {
        rtv = null!; dsv = null!; width = 0; height = 0;
        if (!IsReady) return false;

        var size = PixelSize;
        if (size.Width <= 0 || size.Height <= 0) return false;

        // FINDING: the compositor samples the imported D3D11 texture with a bottom-left origin
        // (Avalonia renders through ANGLE/GL on Windows), so an unflipped D3D scene arrives upside
        // down. We cannot flip inside ViewportCore (shared with the WinForms host), so the surface
        // visual is mirrored on Y instead. Costs nothing; the native HWND mode needs no such fix.
        _visual!.Size = new Vector(Bounds.Width, Bounds.Height);
        _visual.CenterPoint = new Vector3D(Bounds.Width / 2, Bounds.Height / 2, 0);
        _visual.Scale = new Vector3D(1, -1, 1);

        var img = TakeImage(size);
        if (img == null) return false;

        if (_depthW != size.Width || _depthH != size.Height)
        {
            _dsv?.Dispose(); _depthTex?.Dispose();
            _depthTex = _device!.CreateTexture2D(new Texture2DDescription
            {
                Width = (uint)size.Width,
                Height = (uint)size.Height,
                MipLevels = 1,
                ArraySize = 1,
                Format = Format.D24_UNorm_S8_UInt,
                SampleDescription = new SampleDescription(1, 0),
                Usage = ResourceUsage.Default,
                BindFlags = BindFlags.DepthStencil,
            });
            _dsv = _device.CreateDepthStencilView(_depthTex);
            _depthW = size.Width; _depthH = size.Height;
        }

        img.BeginDraw();
        _current = img;
        rtv = img.Rtv; dsv = _dsv!; width = size.Width; height = size.Height;
        return true;
    }

    public void EndFrame()
    {
        if (_current == null) return;
        _context!.Flush();
        _current.Present(_interop!, _surface!, _handleType!);
        _pool.Add(_current);
        _current = null;
        // Nudge the compositor so the freshly published frame is committed even when nothing in the
        // Avalonia tree changed this tick.
        _compositor?.RequestCompositionUpdate(static () => { });
    }

    /// <summary>SwapchainBase semantics: drop images of the wrong size once their present finished,
    /// reuse a ready one only when a second image of that size is still in flight (otherwise the UI
    /// thread can lock up waiting on the keyed mutex), else make a new one.</summary>
    private SharedImage? TakeImage(PixelSize size)
    {
        SharedImage? first = null;
        bool multiple = false;
        for (int i = _pool.Count - 1; i >= 0; i--)
        {
            var img = _pool[i];
            bool ready = img.LastPresent == null || img.LastPresent.Status == TaskStatus.RanToCompletion;
            bool broken = img.LastPresent?.IsFaulted == true;
            bool matches = img.Size == size;
            if (broken || (!matches && ready))
            {
                img.Dispose();
                _pool.RemoveAt(i);
                continue;
            }
            if (matches && ready)
            {
                if (first == null) first = img; else multiple = true;
            }
        }

        var chosen = multiple ? first : null;
        if (chosen == null)
        {
            if (_pool.Count > 6) return null;   // too many in flight; skip this frame
            chosen = new SharedImage(_device!, size, _handleType!);
        }
        else _pool.Remove(chosen);
        return chosen;
    }

    public void Dispose()
    {
        if (_disposed) return;
        _disposed = true;
        FreeGpuResources();
        _surface?.Dispose();
        _context?.Dispose(); _context = null;
        _device?.Dispose(); _device = null;
    }

    // ---------------------------------------------------------------- one shared texture

    private sealed class SharedImage : IDisposable
    {
        public PixelSize Size { get; }
        public Task? LastPresent { get; private set; }
        public ID3D11RenderTargetView Rtv => _rtv;

        private readonly ID3D11Texture2D _texture;
        private readonly ID3D11RenderTargetView _rtv;
        private readonly IDXGIKeyedMutex _mutex;
        private readonly IntPtr _handle;
        private readonly bool _ntHandle;
        private readonly PlatformGraphicsExternalImageProperties _props;
        private ICompositionImportedGpuImage? _imported;

        public SharedImage(ID3D11Device device, PixelSize size, string handleType)
        {
            Size = size;
            _ntHandle = handleType == KnownPlatformGraphicsExternalImageHandleTypes.D3D11TextureNtHandle;
            _texture = device.CreateTexture2D(new Texture2DDescription
            {
                Width = (uint)size.Width,
                Height = (uint)size.Height,
                MipLevels = 1,
                ArraySize = 1,
                Format = Format.B8G8R8A8_UNorm,
                SampleDescription = new SampleDescription(1, 0),
                Usage = ResourceUsage.Default,
                BindFlags = BindFlags.RenderTarget | BindFlags.ShaderResource,
                CPUAccessFlags = CpuAccessFlags.None,
                MiscFlags = _ntHandle
                    ? ResourceOptionFlags.SharedKeyedMutex | ResourceOptionFlags.SharedNTHandle
                    : ResourceOptionFlags.SharedKeyedMutex,
            });
            _mutex = _texture.QueryInterface<IDXGIKeyedMutex>();

            if (_ntHandle)
            {
                using var res1 = _texture.QueryInterface<IDXGIResource1>();
                _handle = res1.CreateSharedHandle(null, Vortice.DXGI.SharedResourceFlags.Read | Vortice.DXGI.SharedResourceFlags.Write, null!);
            }
            else
            {
                using var res = _texture.QueryInterface<IDXGIResource>();
                _handle = res.SharedHandle;
            }

            _rtv = device.CreateRenderTargetView(_texture);
            _props = new PlatformGraphicsExternalImageProperties
            {
                Width = size.Width,
                Height = size.Height,
                Format = PlatformGraphicsExternalImageFormat.B8G8R8A8UNorm,
            };
        }

        public void BeginDraw() => _mutex.AcquireSync(0, int.MaxValue);

        public void Present(ICompositionGpuInterop interop, CompositionDrawingSurface surface, string handleType)
        {
            _mutex.ReleaseSync(1);
            _imported ??= interop.ImportImage(new PlatformHandle(_handle, handleType), _props);
            LastPresent = surface.UpdateWithKeyedMutexAsync(_imported, 1, 0);
        }

        public void Dispose()
        {
            try { _imported?.DisposeAsync(); } catch { /* ignore */ }
            _rtv.Dispose();
            _mutex.Dispose();
            _texture.Dispose();
            if (_ntHandle && _handle != IntPtr.Zero) CloseHandle(_handle);
        }

        [System.Runtime.InteropServices.DllImport("kernel32.dll")]
        private static extern bool CloseHandle(IntPtr h);
    }
}

