using System.Numerics;
using DinoEditor.Viewport;

namespace DinoEditor.App.Input;

public enum EditorCameraKey
{
    Forward,
    Back,
    Left,
    Right,
    Down,
    Up,
}

/// <summary>
/// Unreal-style fly camera (spec section 4): hold the right mouse button to look, WASD to fly,
/// Q down and E up, scroll to change speed, Shift for 3x. Deliberately free of Avalonia types so
/// the maths is unit-tested without a UI; ViewportInputBehavior is the thin Avalonia adapter.
///
/// The camera is fetched through a delegate rather than held, because the Camera instance is
/// replaced whenever the ViewportCore is rebuilt after a device loss.
/// </summary>
public sealed class EditorCameraController
{
    private readonly Func<Camera?> _camera;
    private readonly bool[] _keys = new bool[6];

    public EditorCameraController(Func<Camera?> camera) => _camera = camera;

    /// <summary>Metres per second before the Shift boost. Initialised from and, on every wheel
    /// change, written back to Settings.Current.CameraSpeed by the App wiring (see SpeedChanged).</summary>
    public float BaseSpeed { get; set; } = 20f;

    public float MinSpeed => 0.5f;

    public float MaxSpeed => 2000f;

    public float BoostFactor => 3f;

    /// <summary>Radians of rotation per pixel of mouse movement.</summary>
    public float MouseSensitivity { get; set; } = 0.0035f;

    /// <summary>89 degrees. Straight up would make yaw meaningless and Camera.Right degenerate.</summary>
    public float MaxPitch => 89f * MathF.PI / 180f;

    /// <summary>True while the right mouse button is held over the viewport.</summary>
    public bool Looking { get; set; }

    /// <summary>True while Shift is held.</summary>
    public bool Boost { get; set; }

    public float CurrentSpeed => Boost ? BaseSpeed * BoostFactor : BaseSpeed;

    /// <summary>Raised whenever AdjustSpeed actually changes BaseSpeed, carrying the new value. The
    /// App wiring saves it to Settings.Current.CameraSpeed so the fly speed survives a restart.</summary>
    public event Action<float>? SpeedChanged;

    public void SetKey(EditorCameraKey key, bool down) => _keys[(int)key] = down;

    public void ClearKeys()
    {
        Array.Clear(_keys);
        Looking = false;
        Boost = false;
    }

    /// <summary>Mouse delta in pixels. Right and down are positive, matching Avalonia's screen
    /// coordinates; turning right lowers yaw because Camera.Right is cross(Forward, +Z).</summary>
    public void Look(float dxPixels, float dyPixels)
    {
        if (!Looking) return;
        var cam = _camera();
        if (cam == null) return;

        cam.Yaw = WrapAngle(cam.Yaw - dxPixels * MouseSensitivity);
        cam.Pitch = Math.Clamp(cam.Pitch - dyPixels * MouseSensitivity, -MaxPitch, MaxPitch);
    }

    /// <summary>Wraps an angle into (-pi, pi]. A single conditional subtraction only undoes one
    /// lap, so a fast mouse flick (or a very large synthetic delta) could leave yaw thousands of
    /// radians out of range; the modulo here undoes any number of laps in one step.</summary>
    private static float WrapAngle(float a)
    {
        const float twoPi = MathF.PI * 2f;
        a %= twoPi;
        if (a > MathF.PI) a -= twoPi;
        else if (a < -MathF.PI) a += twoPi;
        return a;
    }

    /// <summary>One scroll notch is one step on a log scale, so the speed range from 0.5 m/s
    /// (walking a room) to 2000 m/s (crossing the map) is reachable in a couple of flicks.</summary>
    public void AdjustSpeed(double scrollDelta)
    {
        if (scrollDelta == 0) return;
        const float stepsPerDecade = 8f;
        float factor = MathF.Pow(10f, (float)scrollDelta / stepsPerDecade);
        float next = Math.Clamp(BaseSpeed * factor, MinSpeed, MaxSpeed);
        if (next == BaseSpeed) return;

        BaseSpeed = next;
        SpeedChanged?.Invoke(BaseSpeed);
    }

    public void Update(float dtSeconds)
    {
        // Unreal gating: the fly keys only move the camera while the right button is held. The keys
        // stay armed either way, so a key held down before the look drag starts takes effect on the
        // very first frame of it rather than needing a re-press.
        var cam = _camera();
        if (cam == null || dtSeconds <= 0f || !Looking) return;

        var move = Vector3.Zero;
        if (_keys[(int)EditorCameraKey.Forward]) move += cam.Forward;
        if (_keys[(int)EditorCameraKey.Back]) move -= cam.Forward;
        if (_keys[(int)EditorCameraKey.Right]) move += cam.Right;
        if (_keys[(int)EditorCameraKey.Left]) move -= cam.Right;
        if (_keys[(int)EditorCameraKey.Up]) move += Vector3.UnitZ;
        if (_keys[(int)EditorCameraKey.Down]) move -= Vector3.UnitZ;

        if (move.LengthSquared() < 1e-8f) return;
        cam.Position += Vector3.Normalize(move) * (CurrentSpeed * dtSeconds);
    }
}

