using Avalonia;
using Avalonia.Controls;
using Avalonia.Input;
using Avalonia.Media;
using DinoEditor.Viewport.Gizmo;

namespace DinoEditor.App.Input;

/// <summary>
/// The Avalonia adapter for <see cref="EditorCameraController"/>. It is a transparent panel that
/// sits between the composition host and the overlay: overlay buttons (which are above it) still
/// receive clicks, everything else lands here.
///
/// Input follows Unreal's editor viewport (spec section 4): the fly keys only move the camera while
/// the right mouse button is held, and the same letters pick a transform mode when it is not. The
/// right mouse button is captured on press so a look drag keeps working when the pointer leaves the
/// panel, and released on button-up or on PointerCaptureLost.
///
/// The pointer and key entry points are split into thin overrides plus internal "core" methods that
/// take plain values, so the gesture state machine is testable without synthesising Avalonia event
/// args (which need a live visual tree to resolve positions).
/// </summary>
public class ViewportInputBehavior : Panel
{
    private static readonly Cursor ArrowCursor = new(StandardCursorType.Arrow);
    private static readonly Cursor LookCursor = new(StandardCursorType.SizeAll);

    /// <summary>How far the pointer may travel between press and release and still count as a
    /// click rather than a drag, in DIPs.</summary>
    private const double ClickSlackDip = 4.0;

    /// <summary>Keys currently held. Avalonia repeats KeyDown while a key is held; the editor
    /// chords and mode keys must only fire on the down edge.</summary>
    private readonly HashSet<Key> _downKeys = new();

    private Point _lastPoint;
    private bool _looking;
    private Point? _pressPos;
    /// <summary>Pointer that armed the pending left click. A second pointer (a touch contact, a pen)
    /// releasing over the panel must not fire the click the mouse armed.</summary>
    private int _pressId;
    private bool _dragging;

    /// <summary>The pointer that owns the current capture, so <see cref="SetCapture"/> can release
    /// it without an event to read it from.</summary>
    private IPointer? _capturePointer;

    public ViewportInputBehavior(EditorCameraController controller)
    {
        Controller = controller;
        Background = Brushes.Transparent;   // required: a null background is not hit-testable
        Focusable = true;
        Cursor = ArrowCursor;
        LostFocus += OnLostFocus;

        AddHandler(DragDrop.DragOverEvent, OnDragOverEvent);
        AddHandler(DragDrop.DragEnterEvent, OnDragOverEvent);
        AddHandler(DragDrop.DropEvent, OnDropEvent);
    }

    public EditorCameraController Controller { get; }

    /// <summary>Raised on G: the shell hides or shows the overlay strip (game view).</summary>
    public event Action? ToggleOverlays;

    /// <summary>Raised on a left click (press and release within <see cref="ClickSlackDip"/> DIPs,
    /// outside a look drag) with the position in DIPs relative to this panel and the modifiers held
    /// at release - Ctrl is what turns a pick into an add/remove rather than a replace.</summary>
    public event Action<Point, KeyModifiers>? Clicked;

    /// <summary>Raised on Escape when no drag is in flight: the shell clears the selection.</summary>
    public event Action? EscapePressed;

    /// <summary>Raised on F: the shell frames the camera on the current selection.</summary>
    public event Action? FocusRequested;

    /// <summary>Raised on the down edge of W/E/R/Q while not looking: the requested gizmo mode.</summary>
    public event Action<GizmoMode>? ModeRequested;

    /// <summary>Raised on Space while not looking: step to the next gizmo mode.</summary>
    public event Action? CycleModeRequested;

    /// <summary>Raised on the down edge of X while not looking: flip the gizmo between World and
    /// Local space. Unreal uses the tilde key, which is awkward on a pt-BR keyboard.</summary>
    public event Action? ToggleSpaceRequested;

    /// <summary>Raised on Delete.</summary>
    public event Action? DeleteRequested;

    /// <summary>Raised on Ctrl+D.</summary>
    public event Action? DuplicateRequested;

    /// <summary>Raised on Ctrl+Z.</summary>
    public event Action? UndoRequested;

    /// <summary>Raised on Ctrl+Y and Ctrl+Shift+Z.</summary>
    public event Action? RedoRequested;

    /// <summary>Raised on End: drop the selection onto the ground below it.</summary>
    public event Action? GroundDropRequested;

    /// <summary>Raised once the left button has travelled past <see cref="ClickSlackDip"/>, with the
    /// position where the button went down (not the current one) so a gizmo can pick the handle the
    /// drag started on.</summary>
    public event Action<Point>? DragStarted;

    /// <summary>Raised on every pointer move while a left drag is in flight.</summary>
    public event Action<Point>? Dragging;

    /// <summary>Raised when the left button is released and a drag was in flight.</summary>
    public event Action<Point>? DragEnded;

    /// <summary>Raised when Escape (or focus loss) aborts a drag in flight. The consumer reverts.</summary>
    public event Action? DragCancelled;

    /// <summary>Raised on a pointer move with no button held, so a gizmo can highlight its handles.</summary>
    public event Action<Point>? PointerHover;

    /// <summary>Raised while a drag-and-drop payload is over the viewport. Returns whether the
    /// payload is accepted; the drag effects follow the answer. Avalonia 12 replaced IDataObject
    /// with IDataTransfer, so the payload arrives as the latter.</summary>
    public event Func<Point, IDataTransfer, bool>? DragOverCheck;

    /// <summary>Raised when an accepted drag-and-drop payload is dropped on the viewport.</summary>
    public event Action<Point, IDataTransfer>? Dropped;

    /// <summary>True while a left-button drag is in flight.</summary>
    public bool IsDragging => _dragging;

    /// <summary>Turns this panel into a drag-and-drop target (the Content Browser drops props here).</summary>
    public void SetAllowDrop(bool allow) => DragDrop.SetAllowDrop(this, allow);

    protected override void OnPointerPressed(PointerPressedEventArgs e)
    {
        base.OnPointerPressed(e);
        Focus();

        var props = e.GetCurrentPoint(this).Properties;
        _capturePointer = e.Pointer;
        if (PressCore(e.GetPosition(this), props.IsLeftButtonPressed, props.IsRightButtonPressed, e.Pointer.Id))
            e.Handled = true;
    }

    protected override void OnPointerMoved(PointerEventArgs e)
    {
        base.OnPointerMoved(e);
        var props = e.GetCurrentPoint(this).Properties;
        bool anyButton = props.IsLeftButtonPressed || props.IsRightButtonPressed || props.IsMiddleButtonPressed;
        if (MoveCore(e.GetPosition(this), anyButton, e.Pointer.Id)) e.Handled = true;
    }

    protected override void OnPointerReleased(PointerReleasedEventArgs e)
    {
        base.OnPointerReleased(e);
        if (ReleaseCore(e.GetPosition(this), e.InitialPressMouseButton, e.Pointer.Id, e.KeyModifiers))
            e.Handled = true;
    }

    protected override void OnPointerCaptureLost(PointerCaptureLostEventArgs e)
    {
        base.OnPointerCaptureLost(e);
        CancelDrag();
        StopLooking();
    }

    protected override void OnPointerWheelChanged(PointerWheelEventArgs e)
    {
        base.OnPointerWheelChanged(e);
        // Spec section 4: scroll changes fly speed while looking. Outside a look drag the wheel is
        // left alone so a future zoom/orbit gesture can claim it. Avalonia normalises the wheel
        // delta itself (Win32 divides the raw WM_MOUSEWHEEL value by WHEEL_DELTA=120 before raising
        // the event), so Delta.Y is already ~1.0 per notch - no extra scaling here.
        if (!_looking) return;
        Controller.AdjustSpeed(e.Delta.Y);
        e.Handled = true;
    }

    protected override void OnKeyDown(KeyEventArgs e)
    {
        base.OnKeyDown(e);
        bool repeat = !_downKeys.Add(e.Key);
        if (KeyDownCore(e.Key, e.KeyModifiers, repeat)) e.Handled = true;
    }

    protected override void OnKeyUp(KeyEventArgs e)
    {
        base.OnKeyUp(e);
        _downKeys.Remove(e.Key);
        if (SetFlyKey(e.Key, down: false)) e.Handled = true;
    }

    /// <summary>Press half of the pointer state machine. Returns whether the event was consumed.</summary>
    internal bool PressCore(Point pos, bool left, bool right, int pointerId)
    {
        if (right)
        {
            // A right press during a left drag aborts it: the mapper is bailing out to look around.
            CancelDrag();
            _looking = true;
            Controller.Looking = true;
            _lastPoint = pos;
            SetCapture(true);
            Cursor = LookCursor;
            return true;
        }

        // A left press only arms a click; the pick happens on release, and only if the pointer
        // barely moved. Past the slack radius it becomes a drag instead (gizmo, marquee).
        if (left && !_looking)
        {
            _pressPos = pos;
            _pressId = pointerId;
            return true;
        }

        return false;
    }

    /// <summary>Move half of the pointer state machine. Returns whether the event was consumed.</summary>
    internal bool MoveCore(Point pos, bool anyButtonHeld, int pointerId)
    {
        if (_looking)
        {
            Controller.Look((float)(pos.X - _lastPoint.X), (float)(pos.Y - _lastPoint.Y));
            _lastPoint = pos;
            return true;
        }

        if (_pressPos is Point press && pointerId == _pressId)
        {
            if (!anyButtonHeld)
            {
                // A release this panel never saw. A left press takes no capture until the drag
                // begins, so a sub-slack move off the panel followed by a release over another
                // control leaves the arm stale: drop it, or the next button-free hover move back
                // over the viewport is past the slack radius and would start a drag the mapper
                // never began. Once the drag IS in flight the same button-free move means the
                // button came up somewhere this panel cannot see, and the drag has to be unwound
                // properly - capture released and the consumer told to revert - because
                // ReleaseCore keys its own cleanup off _pressPos and would silently no-op.
                if (_dragging) CancelDrag();
                else _pressPos = null;
            }
            else
            {
                if (!_dragging)
                {
                    double dx = pos.X - press.X, dy = pos.Y - press.Y;
                    if (dx * dx + dy * dy <= ClickSlackDip * ClickSlackDip) return true;
                    _dragging = true;
                    SetCapture(true);
                    DragStarted?.Invoke(press);
                }
                Dragging?.Invoke(pos);
                return true;
            }
        }

        if (!anyButtonHeld)
        {
            PointerHover?.Invoke(pos);
            return false;   // hover never consumes the move: it is a passive highlight
        }

        return false;
    }

    /// <summary>Release half of the pointer state machine. Returns whether the event was consumed.</summary>
    internal bool ReleaseCore(Point pos, MouseButton initialButton, int pointerId, KeyModifiers modifiers)
    {
        if (_looking && initialButton == MouseButton.Right)
        {
            StopLooking();
            SetCapture(false);
            return true;
        }

        if (initialButton == MouseButton.Left && _pressPos is Point press && pointerId == _pressId)
        {
            _pressPos = null;
            if (_dragging)
            {
                _dragging = false;
                SetCapture(false);
                DragEnded?.Invoke(pos);
                return true;
            }

            double dx = pos.X - press.X, dy = pos.Y - press.Y;
            if (dx * dx + dy * dy <= ClickSlackDip * ClickSlackDip)
            {
                Clicked?.Invoke(pos, modifiers);
                return true;
            }
        }

        return false;
    }

    /// <summary>
    /// The whole key map. <paramref name="repeat"/> is true for an auto-repeat KeyDown: the fly keys
    /// do not care, but the mode keys and chords must only fire on the down edge.
    /// Returns whether the event was consumed.
    /// </summary>
    internal bool KeyDownCore(Key key, KeyModifiers modifiers, bool repeat)
    {
        bool ctrl = modifiers.HasFlag(KeyModifiers.Control);
        bool shift = modifiers.HasFlag(KeyModifiers.Shift);

        if (ctrl)
        {
            // Ctrl turns the letters into editor chords, so the fly keys stay disarmed: Ctrl+D must
            // not leave the camera strafing right once the chord is released.
            if (repeat) return false;
            switch (key)
            {
                case Key.D: DuplicateRequested?.Invoke(); return true;
                case Key.Z:
                    if (shift) RedoRequested?.Invoke(); else UndoRequested?.Invoke();
                    return true;
                case Key.Y: RedoRequested?.Invoke(); return true;
                default: return false;
            }
        }

        // The fly keys stay armed whether or not the right button is down, so a key held before the
        // look drag starts takes effect on the first frame of it. EditorCameraController.Update is
        // what gates the movement on Looking.
        bool handled = SetFlyKey(key, down: true);
        if (repeat) return handled;

        if (!_looking)
        {
            switch (key)
            {
                case Key.Q: ModeRequested?.Invoke(GizmoMode.Select); return true;
                case Key.W: ModeRequested?.Invoke(GizmoMode.Translate); return true;
                case Key.E: ModeRequested?.Invoke(GizmoMode.Rotate); return true;
                case Key.R: ModeRequested?.Invoke(GizmoMode.Scale); return true;
                case Key.Space: CycleModeRequested?.Invoke(); return true;
                case Key.X: ToggleSpaceRequested?.Invoke(); return true;
            }
        }

        switch (key)
        {
            case Key.Delete: DeleteRequested?.Invoke(); return true;
            case Key.End: GroundDropRequested?.Invoke(); return true;
            case Key.F: FocusRequested?.Invoke(); return true;
            case Key.G: ToggleOverlays?.Invoke(); return true;
            case Key.Escape:
                // Escape cancels a drag first; only an idle Escape clears the selection.
                if (_dragging) CancelDrag();
                else EscapePressed?.Invoke();
                return true;
        }

        return handled;
    }

    private void OnDragOverEvent(object? sender, DragEventArgs e)
    {
        bool accepted = DragOverCheck?.Invoke(e.GetPosition(this), e.DataTransfer) ?? false;
        e.DragEffects = accepted ? DragDropEffects.Copy : DragDropEffects.None;
        e.Handled = true;
    }

    private void OnDropEvent(object? sender, DragEventArgs e)
    {
        var pos = e.GetPosition(this);
        bool accepted = DragOverCheck?.Invoke(pos, e.DataTransfer) ?? false;
        e.DragEffects = accepted ? DragDropEffects.Copy : DragDropEffects.None;
        if (accepted) Dropped?.Invoke(pos, e.DataTransfer);
        e.Handled = true;
    }

    private void OnLostFocus(object? sender, Avalonia.Interactivity.RoutedEventArgs e)
    {
        // Alt-tabbing away with W held must not leave the camera flying forever, nor leave a gizmo
        // drag half applied. StopLooking also clears any stale right-button capture state and resets
        // the cursor - focus loss during a look-drag must not leave the SizeAll cursor stuck.
        _downKeys.Clear();
        Controller.ClearKeys();
        CancelDrag();
        StopLooking();
        _pressPos = null;   // a press that never released must not fire a click on the next one
    }

    /// <summary>Aborts a left drag in flight, if any, and tells the consumer to revert.</summary>
    private void CancelDrag()
    {
        if (!_dragging) return;
        _dragging = false;
        _pressPos = null;
        SetCapture(false);
        DragCancelled?.Invoke();
    }

    private void StopLooking()
    {
        _looking = false;
        Controller.Looking = false;
        Cursor = ArrowCursor;
    }

    /// <summary>Takes or releases the pointer capture. Virtual so tests can drive the state machine
    /// without a real <see cref="IPointer"/>.</summary>
    protected virtual void SetCapture(bool capture)
    {
        _capturePointer?.Capture(capture ? this : null);
        if (!capture) _capturePointer = null;
    }

    /// <summary>Arms or disarms one fly key. Returns whether the key is a fly key at all.</summary>
    private bool SetFlyKey(Key key, bool down)
    {
        switch (key)
        {
            case Key.W: Controller.SetKey(EditorCameraKey.Forward, down); return true;
            case Key.S: Controller.SetKey(EditorCameraKey.Back, down); return true;
            case Key.A: Controller.SetKey(EditorCameraKey.Left, down); return true;
            case Key.D: Controller.SetKey(EditorCameraKey.Right, down); return true;
            case Key.Q: Controller.SetKey(EditorCameraKey.Down, down); return true;
            case Key.E: Controller.SetKey(EditorCameraKey.Up, down); return true;
            case Key.LeftShift:
            case Key.RightShift: Controller.Boost = down; return true;
            default: return false;
        }
    }
}

