using Avalonia.Data;
using Avalonia.Markup.Xaml;
using DinoEditor.App.Services;

namespace DinoEditor.App.Localization;

/// <summary>{Loc SomeKey} in AXAML. Returns a Binding to the LocKey observable rather than a
/// plain string, which is what makes the language switch live: LocalizationService raises
/// PropertyChanged on every key it has ever handed out.</summary>
public sealed class LocExtension : MarkupExtension
{
    public LocExtension() { }

    public LocExtension(string key) => Key = key;

    public string Key { get; set; } = string.Empty;

    public override object ProvideValue(IServiceProvider serviceProvider)
        => new Binding(nameof(LocKey.Value))
        {
            Source = LocalizationService.Instance.Key(Key),
            Mode = BindingMode.OneWay,
        };
}

