// DinoEditorForGTA - the product shell (Phase 1b, Drop 1).
//
// the GTA V install is READ-ONLY. Nothing under src\ThirdParty\ or src\ShellBakeoff.* is modified.

using System.Runtime;
using Avalonia;
using DinoEditor.App.Services;

namespace DinoEditor.App;

/// <summary>Parsed command line. Kept tiny on purpose: the app is not a CLI tool, these flags
/// exist so the shell can be started headlessly for a smoke check and for the flight harness.</summary>
public sealed class CommandLine
{
    public bool Smoke { get; private init; }
    public bool Flight { get; private init; }
    public string? Language { get; private init; }

    /// <summary>--exit-after N: run for real (game data, world, render) and then shut down, so a
    /// render check can be captured without a person sitting at the window.</summary>
    public double? ExitAfterSeconds { get; private init; }

    /// <summary>--shot-after N PATH: once the session is running, open the Content Drawer, let it
    /// settle and write a whole-window PNG to PATH, then keep running. A development aid for the
    /// task screenshots; the product never passes it.</summary>
    public double? ShotAfterSeconds { get; private init; }

    /// <summary>Where --shot-after writes its PNG.</summary>
    public string? ShotPath { get; private init; }

    /// <summary>--bake-thumbs N: with --flight, request thumbnails for the N most-placed
    /// archetypes two seconds into the flight, so the flight measures the asset browser under a
    /// realistic "scrolling the drawer while flying" load. 0 disables it.</summary>
    public int BakeThumbs { get; private init; }

    /// <summary>--pick-at X Y: once the session is running and the stream has settled, issue one
    /// synthetic left click at (X, Y) DIPs inside the viewport panel and leave the selection in
    /// place, so --shot-after can capture outline + label + Details + Outliner unattended.
    /// A development aid for the task screenshots; the product never passes it.</summary>
    public (int X, int Y)? PickAt { get; private init; }

    /// <summary>--place-demo N: once the session is running and the stream has settled, place N
    /// props on the ground in front of the camera, select the first and switch the gizmo to
    /// Translate, so --shot-after captures the edit layer and --flight measures the frame with a
    /// project loaded. A development aid; the product never passes it.</summary>
    public int PlaceDemo { get; private init; }

    /// <summary>--save-demo PATH: writes the project to PATH once --place-demo has placed its props,
    /// or right after --open loaded one, so the save/open round trip can be checked without a person
    /// at the file picker. Requires --place-demo or a successful --open: on its own there is no
    /// project worth writing and the run logs `[save-demo] ignored: ...` instead.</summary>
    public string? SaveDemoPath { get; private init; }

    /// <summary>--open PATH: opens the project at PATH once the session is running.</summary>
    public string? OpenPath { get; private init; }

    /// <summary>--export-demo FOLDER: exports the open project as a .ymap resource into FOLDER
    /// once --place-demo has placed its props or --open has loaded a project, so the production server
    /// bench gets a folder to `ensure` without a person at the folder picker. Requires a project
    /// with entities; on its own the run logs `[export-demo] ignored: ...` instead.</summary>
    public string? ExportDemoFolder { get; private init; }

    /// <summary>
    /// --import-vanilla &lt;stem&gt;: import that ymap out of the GTA V install through the SAME
    /// ProjectService.ImportMap path the Import button uses, then fall into --save-demo /
    /// --export-demo.
    /// </summary>
    /// <remarks>
    /// A bench harness, not a product path. It exists so a round-trip run does not have to be
    /// hand-driven through the UI, and - the point - so what the bench loads is the output of the
    /// REAL import and export code rather than a probe's reimplementation of it. A probe that
    /// converts entities its own way can produce a file the editor would never emit, and then a
    /// green run in game proves nothing about the editor.
    /// </remarks>
    public string? ImportVanilla { get; private init; }

    /// <summary>--lift &lt;archetypeName&gt; &lt;metres&gt;: raise every entity of that archetype in
    /// the active map. A bench harness - it makes an imported tile DISTINGUISHABLE from the vanilla
    /// copy it replaces, which is the whole difficulty of an override experiment: a faithful copy
    /// loads and looks exactly like the file it replaced, so a correct result and a total failure
    /// are the same screenshot.</summary>
    public string? LiftArchetype { get; private init; }

    /// <summary>Metres for <see cref="LiftArchetype"/>.</summary>
    public float Lift { get; private init; }

    /// <summary>--rename &lt;name&gt;: renames the active map, which renames the exported ymap and
    /// its internal name hash together. The control arm of an override experiment: the SAME bytes
    /// shipped under a name the base game has never heard of, so "our file is malformed" and "the
    /// engine refuses to override this tile" stop looking identical.</summary>
    public string? RenameTo { get; private init; }

    /// <summary>
    /// --as-authored: turns the imported map from a PINNED replacement into an ordinary authored
    /// one, so export names the file after the map instead of after the tile it came from.
    /// </summary>
    /// <remarks>
    /// Needed for the control arm of an override experiment, because a pinned map keeps its source
    /// file name BY DESIGN - it exists to replace that exact file. Shipping the same content under
    /// a new name is what separates "the engine will not override this tile" from "our file is
    /// malformed", and those two look identical from inside the game otherwise.
    ///
    /// It DROPS the pinned metadata (parent hash, source flags), which is correct for a standalone
    /// resource and is what every authored export already writes.
    /// </remarks>
    public bool AsAuthored { get; private init; }

    public static CommandLine Parse(string[] args)
    {
        bool smoke = false, flight = false;
        string? lang = null;
        double? exitAfter = null, shotAfter = null;
        string? shotPath = null;
        int bakeThumbs = 0;
        (int X, int Y)? pickAt = null;
        int placeDemo = 0;
        string? saveDemoPath = null, openPath = null, exportDemoFolder = null, importVanilla = null;
        string? liftArchetype = null, renameTo = null;
        bool asAuthored = false;
        float lift = 0f;
        for (int i = 0; i < args.Length; i++)
        {
            switch (args[i])
            {
                case "--smoke": smoke = true; break;
                case "--flight": flight = true; break;
                case "--lang" when i + 1 < args.Length: lang = args[++i]; break;
                case "--exit-after" when i + 1 < args.Length &&
                    double.TryParse(args[i + 1], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out double sec):
                    exitAfter = sec; i++; break;
                case "--shot-after" when i + 2 < args.Length &&
                    double.TryParse(args[i + 1], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out double shotSec):
                    shotAfter = shotSec; shotPath = args[i + 2]; i += 2; break;
                case "--bake-thumbs" when i + 1 < args.Length &&
                    int.TryParse(args[i + 1], System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out int thumbs):
                    bakeThumbs = Math.Max(0, thumbs); i++; break;
                case "--pick-at" when i + 2 < args.Length &&
                    int.TryParse(args[i + 1], System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out int pickX) &&
                    int.TryParse(args[i + 2], System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out int pickY):
                    pickAt = (pickX, pickY); i += 2; break;
                case "--place-demo" when i + 1 < args.Length &&
                    int.TryParse(args[i + 1], System.Globalization.NumberStyles.Integer,
                        System.Globalization.CultureInfo.InvariantCulture, out int demo):
                    placeDemo = Math.Max(0, demo); i++; break;
                case "--save-demo" when i + 1 < args.Length:
                    saveDemoPath = args[++i]; break;
                case "--open" when i + 1 < args.Length:
                    openPath = args[++i]; break;
                case "--import-vanilla" when i + 1 < args.Length:
                    importVanilla = args[++i]; break;
                case "--rename" when i + 1 < args.Length:
                    renameTo = args[++i]; break;
                case "--as-authored":
                    asAuthored = true; break;
                case "--lift" when i + 2 < args.Length &&
                    float.TryParse(args[i + 2], System.Globalization.NumberStyles.Float,
                        System.Globalization.CultureInfo.InvariantCulture, out float liftBy):
                    liftArchetype = args[i + 1]; lift = liftBy; i += 2; break;
                case "--export-demo" when i + 1 < args.Length:
                    exportDemoFolder = args[++i]; break;
            }
        }
        return new CommandLine
        {
            Smoke = smoke, Flight = flight, Language = lang, ExitAfterSeconds = exitAfter,
            ShotAfterSeconds = shotAfter, ShotPath = shotPath, BakeThumbs = bakeThumbs,
            PickAt = pickAt, PlaceDemo = placeDemo, SaveDemoPath = saveDemoPath, OpenPath = openPath,
            ExportDemoFolder = exportDemoFolder, ImportVanilla = importVanilla,
            LiftArchetype = liftArchetype, Lift = lift, RenameTo = renameTo, AsAuthored = asAuthored,
        };
    }
}

public static class Program
{
    [STAThread]
    public static int Main(string[] args)
    {
        // Installed before anything else can throw: an exception during AppBuilder or window
        // construction must still land in the log file and, once a window exists, the dialog.
        CrashHandler.Install();
        CrashHandler.Write($"DinoEditorForGTA starting {DateTime.Now:u}");

        // Matches StreamSpike and the bake-off: keeps gen2 incremental while the decode threads
        // churn, which is measurable in the frame-time tail.
        GCSettings.LatencyMode = GCLatencyMode.SustainedLowLatency;

        App.Cli = CommandLine.Parse(args);
        BuildAvaloniaApp().StartWithClassicDesktopLifetime(args);
        return 0;
    }

    public static AppBuilder BuildAvaloniaApp()
        => AppBuilder.Configure<App>()
            .UsePlatformDetect()
            .WithInterFont()
            .LogToTrace();
}

