  { file: "netty-handler-4.1.82.Final.jar", path: "io/netty/netty-handler/4.1.82.Final", sha256: "31015505983dc57eec491ad4873411ba51f0f3beb24d22d509336c72511019cb", license: "Apache-2.0" },
