using CommunityToolkit.Mvvm.ComponentModel;
using DinoEditor.Formats;

namespace DinoEditor.App.Projects;

/// <summary>
/// Where a <see cref="MapDocument"/> came from. Authored maps are the mapper's own work and always
/// auto-partition on export; imported maps carry the provenance of the ymap they were read from and
/// are exported back out as a single, unsplit file so the round trip stays recognisable.
/// </summary>
public enum MapOrigin
{
    Authored,
    ImportedResource,
    ImportedVanilla,
}

/// <summary>
/// One named map inside a project: the layers and entities that make up a single exported
/// <c>.ymap</c>, plus enough provenance to write it back out the way it was read in.
/// </summary>
/// <remarks>
/// Observable for the same reason as <see cref="Layer"/>: a future map list panel binds to these
/// rows directly. The id is assigned once from <see cref="Project.NextId"/> and never changes, so
/// commands can refer to a map across undo the same way they refer to a layer.
///
/// This deliberately carries no streaming extent or entity extent fields. Those are DERIVED by
/// <c>YmapWriter.ComputeExtents</c> from the entities at export time; storing a copy here would be a
/// second source of truth that could drift from the entities it describes.
/// </remarks>
public sealed partial class MapDocument : ObservableObject
{
    /// <summary>Stable identity, unique within the project.</summary>
    public int Id;

    [ObservableProperty]
    private string _name = "Map";

    [ObservableProperty]
    private bool _visible = true;

    /// <summary>
    /// True once the MAPPER has named this map themselves, rather than it inheriting a name.
    /// </summary>
    /// <remarks>
    /// A project's sole authored map is named after the project so a fresh project called
    /// "Downtown" does not export "untitled.ymap" (see ProjectService.SoleAuthoredMap). That
    /// convenience has to stop the moment the mapper picks a name of their own, or renaming the
    /// PROJECT would silently rename their ymap out from under them.
    /// </remarks>
    public bool NameIsExplicit;

    /// <summary>Where this map came from, and therefore how it is exported.</summary>
    public MapOrigin Origin = MapOrigin.Authored;

    /// <summary>The file this map was imported from, inside its rpf chain. Null for an authored map.</summary>
    public string? SourcePath;

    /// <summary>
    /// <see cref="SourcePath"/> without its directory or <c>.ymap</c> extension - the name the
    /// ENGINE registered this tile under. Null for an authored map, which has no source.
    ///
    /// This, never <see cref="Name"/>, is the identity of an imported map. Name is a display
    /// string the mapper can retype at any moment from the Outliner; the engine's registration
    /// does not move when they do. Keying anything on Name means a rename silently repoints it:
    /// it un-hid Rockstar's copy of the tile so both drew at once, and renaming to another real
    /// tile's name hid the WRONG tile. Derived the same way <see cref="Region.YmapNames"/> is, so
    /// the two match, and deliberately NOT sanitized - it is compared against raw file names.
    /// </summary>
    public string? SourceBaseName
    {
        get
        {
            string? source = SourcePath;
            if (string.IsNullOrWhiteSpace(source)) return null;

            string leaf = source.Replace('\\', '/');
            int slash = leaf.LastIndexOf('/');
            if (slash >= 0) leaf = leaf[(slash + 1)..];
            if (leaf.EndsWith(".ymap", StringComparison.OrdinalIgnoreCase))
                leaf = leaf[..^".ymap".Length];
            return leaf.Length > 0 ? leaf : null;
        }
    }

    /// <summary>Jenkins hash of the original ymap's <c>name</c>. Zero for an authored map.</summary>
    public int SourceNameHash;

    /// <summary>Jenkins hash of the original ymap's <c>parent</c>. Zero for an authored map.</summary>
    public int SourceParentHash;

    /// <summary>The original ymap's <c>flags</c>. Zero for an authored map.</summary>
    public uint SourceFlags;

    /// <summary>The original ymap's <c>contentFlags</c>. Zero for an authored map.</summary>
    public uint SourceContentFlags;

    /// <summary>
    /// CMapData.physicsDictionaries from the file this map was imported from, carried verbatim so
    /// a re-export reproduces it. Empty for an authored map.
    /// </summary>
    /// <remarks>
    /// Opaque 4-byte joaat hashes, never interpreted here - see YmapRecord.PhysicsDictionaries.
    /// Persisted with the map because the source file may be unreachable at export time, the same
    /// reason SourceFlags and SourceParentHash are.
    /// </remarks>
    public List<uint> PhysicsDictionaries = new();

    /// <summary>CMapData.carGenerators from the imported file, carried verbatim so a re-export
    /// reproduces it. Empty for an authored map.</summary>
    public byte[] CarGensData = Array.Empty<byte>();
    public int CarGenCount;
    public byte[] TimeCyclesData = Array.Empty<byte>();
    public int TimeCycleCount;

    /// <summary>
    /// Content the source ymap carried that this editor does not read, and therefore cannot write
    /// back. Non-<see cref="YmapBlocks.None"/> makes this map a hard export FAILURE naming the
    /// members - see <see cref="DinoEditor.Formats.YmapBlocks"/> for the measurement behind that
    /// ruling. <see cref="YmapBlocks.None"/> for an authored map, which by definition holds nothing
    /// it did not get from this editor.
    /// </summary>
    /// <remarks>
    /// Captured at IMPORT and persisted, deliberately - NOT re-read from the source file at export.
    /// The source may be inside the read-only install, on a drive that is no longer mounted, or
    /// simply gone by the time the mapper exports; a check that needs the original file present
    /// would silently pass in exactly the case it exists to catch.
    /// </remarks>
    public YmapBlocks UnsupportedBlocks;

    /// <summary>
    /// Entities in the source ymap this editor could not represent, and so did not import: an MLO
    /// instance (an interior) or an entity under a struct this reader does not know. Like
    /// <see cref="UnsupportedBlocks"/> this is a hard export failure - exporting would drop them
    /// silently - and it is recorded at import for the same reason.
    /// </summary>
    public int UnconvertedEntityCount;

    /// <summary>
    /// The <c>patchday*</c> packs that re-ship the vanilla tile this map replaces, or empty when
    /// none do. NON-EMPTY MEANS AN EXPORT WOULD BE SILENTLY IGNORED BY THE GAME, so it is a hard
    /// export failure, exactly like <see cref="UnsupportedBlocks"/>.
    /// </summary>
    /// <remarks>
    /// PROVEN IN GAME 26-27/08/2026 (E1): a same-named streamed ymap overrides a vanilla tile,
    /// unless a patchday pack re-ships that file, in which case the engine re-registers the patchday
    /// copy over ours and nothing anywhere reports it. Only meaningful for
    /// <see cref="MapOrigin.ImportedVanilla"/>; a map resource of the mapper's own is not replacing
    /// a base-game tile at all.
    ///
    /// Captured at import and persisted, for the same reason as <see cref="UnsupportedBlocks"/>:
    /// the answer needs the GTA install, which may not be configured or loaded when the mapper
    /// finally exports.
    /// </remarks>
    public List<string> OverrideIgnoredByPacks = new();

    /// <summary>
    /// Patchday packs that could not be walked when this map was imported, so
    /// <see cref="OverrideIgnoredByPacks"/> being empty is "not found", not "not shipped".
    /// </summary>
    /// <remarks>
    /// The patchday gate FAILS OPEN: a pack that cannot be opened contributes no ymap names, so it
    /// reports nothing shipping the tile, so the override looks safe. Before this the case was
    /// recorded only in the app log, and a mapper who never opens the log saw the same confident
    /// green whether the question had been answered or merely skipped. Captured and persisted
    /// beside the answer for the same reason the answer is: the install may be gone by export time.
    /// </remarks>
    public List<string> OverrideCheckUnreadablePacks = new();

    /// <summary>
    /// Whether the BASE GAME ships the tile this map replaces, which is what decides whether the
    /// override works at all. True means export refuses.
    /// </summary>
    /// <remarks>
    /// MEASURED over six in-game runs, 27-28/08/2026 (docs/bench/E1-override-experiment.md): a
    /// stream resource overrides a tile the base game does NOT ship and cannot override one it
    /// does, whatever the file holds and whoever wrote it. Run G is the one that clears our writer -
    /// Rockstar's own bytes with 56 Z values patched and every other field asserted identical were
    /// still ignored.
    ///
    /// This REPLACES <see cref="OverrideIgnoredByPacks"/> as the export gate. Those packs are still
    /// captured and still shown, because they correlate with real DLC behaviour and cost nothing to
    /// carry, but they no longer refuse anything: patchday was never the rule, and the patchday
    /// tiles E1 tested failed because they were base-game tiles too.
    ///
    /// Captured at import and persisted, for the same reason as <see cref="UnsupportedBlocks"/>:
    /// the answer needs the GTA install, which may not be configured or loaded at export time.
    /// </remarks>
    public bool OverrideShippedByBaseGame;

    /// <summary>
    /// Archives that could not be walked when this map was imported, so
    /// <see cref="OverrideShippedByBaseGame"/> being FALSE is "not found", not "not shipped".
    /// </summary>
    /// <remarks>
    /// The provenance scan fails OPEN, and asymmetrically. A TRUE verdict is always trustworthy -
    /// the name was seen in an x64 archive - but a FALSE one is only as good as the scan behind it,
    /// and an x64 archive that would not open takes its base-game tiles with it. Non-empty here
    /// means the mapper is warned rather than refused: a refusal they cannot act on is worse than a
    /// warning they can.
    /// </remarks>
    public List<string> OverrideCheckUnscannedArchives = new();

    /// <summary>
    /// Whether export is allowed to split this map across several ymap files when it grows past the
    /// single-page limit. True for an authored map; false for an imported one, which must round-trip
    /// as the single file it was read from.
    /// </summary>
    public bool AutoPartition = true;

    public List<Layer> Layers = new();

    public List<ProjectEntity> Entities = new();
}

