using System.Linq;
using System.Numerics;

namespace DinoEditor.App.Projects;

/// <summary>
/// Everything a <c>.dinoproj</c> holds: the layers, the entities the mapper placed, which layer is
/// active, and a camera bookmark so reopening a project puts the viewport back where it was left.
/// </summary>
/// <remarks>
/// This is a plain container with no behaviour: all mutation goes through <c>ProjectService</c> as
/// undoable commands, so nothing here raises events or enforces rules of its own.
/// </remarks>
public sealed class Project
{
    /// <summary>Display name, shown in the window title. Independent of the file name.</summary>
    public string Name = "Untitled";

    /// <summary>
    /// Every map the project holds. INVARIANT: never empty - a project always has somewhere for
    /// <see cref="ActiveMap"/> to resolve to.
    /// </summary>
    public List<MapDocument> Maps = new();

    /// <summary>Id of the map new layers and entities are placed into. See <see cref="ActiveMap"/>.</summary>
    public int ActiveMapId;

    /// <summary>
    /// The map <see cref="ActiveMapId"/> names, or <c>Maps[0]</c> if that id does not resolve to one
    /// of <see cref="Maps"/>. Every existing caller of <see cref="Layers"/>/<see cref="Entities"/>
    /// reads and writes through this map without knowing maps exist at all.
    /// </summary>
    public MapDocument ActiveMap
    {
        get
        {
            foreach (var map in Maps)
            {
                if (map.Id == ActiveMapId) return map;
            }

            return Maps[0];
        }
    }

    /// <summary>
    /// The active map's layers, by reference: <c>.Add</c>/<c>.Remove</c>/indexing on this property
    /// mutate <see cref="ActiveMap"/>.Layers directly, because it IS that list. This is what keeps
    /// every caller that predates maps compiling and behaving identically.
    /// </summary>
    public List<Layer> Layers => ActiveMap.Layers;

    /// <summary>The active map's entities, by reference. See <see cref="Layers"/>.</summary>
    public List<ProjectEntity> Entities => ActiveMap.Entities;

    /// <summary>Every layer in every map. Layer ids are project-global, so selection can use this to search across maps.</summary>
    public IEnumerable<Layer> AllLayers => Maps.SelectMany(m => m.Layers);

    /// <summary>Every entity in every map. Entity ids are project-global, so selection can use this to search across maps.</summary>
    public IEnumerable<ProjectEntity> AllEntities => Maps.SelectMany(m => m.Entities);

    /// <summary>Layer new entities are placed into. Always the id of a layer in <see cref="Layers"/>.</summary>
    public int ActiveLayerId;

    /// <summary>
    /// Monotonic id source shared by maps, layers and entities. Never reused within a session so an
    /// undone-then-redone placement comes back with the same id it had.
    /// </summary>
    public int NextId = 1;

    /// <summary>Camera bookmark saved with the project; null when the project has never been saved from a viewport.</summary>
    public Vector3? CameraPosition;

    public float CameraYaw;

    public float CameraPitch;

    /// <summary>A brand new project: one authored map with one visible layer, active, and nothing in it.</summary>
    public static Project CreateDefault()
    {
        var project = new Project();
        var map = new MapDocument
        {
            Id = project.NextId++,
            Name = project.Name,
            Visible = true,
            Origin = MapOrigin.Authored,
            AutoPartition = true,
        };
        project.Maps.Add(map);
        project.ActiveMapId = map.Id;

        var layer = new Layer { Id = project.NextId++, Name = "Layer 1" };
        map.Layers.Add(layer);
        project.ActiveLayerId = layer.Id;
        return project;
    }

    public Layer? FindLayer(int id)
    {
        foreach (var layer in AllLayers)
        {
            if (layer.Id == id) return layer;
        }

        return null;
    }

    public ProjectEntity? FindEntity(int id)
    {
        foreach (var entity in AllEntities)
        {
            if (entity.Id == id) return entity;
        }

        return null;
    }
}

