using System.Numerics;
using CommunityToolkit.Mvvm.ComponentModel;
using DinoEditor.Formats.Ymap;

namespace DinoEditor.App.Projects;

/// <summary>
/// One user placed entity. Vanilla map placements live in <c>Region.Placements</c> and are never
/// mutated; everything the mapper creates is one of these, owned by the project and drawn through
/// <c>ProjectEntitySource</c>.
/// </summary>
/// <remarks>
/// The archetype hash is the identity (it is what a ymap export writes and what resolves to a slot
/// in this install); the name is carried alongside it for display and for files opened on a machine
/// where the archetype is missing. Scale is uniform only - the engine and the export path both
/// treat non-uniform scale as unsupported.
/// </remarks>
public sealed partial class ProjectEntity : ObservableObject
{
    /// <summary>Stable identity, unique within the project, assigned from <see cref="Project.NextId"/>.</summary>
    public int Id;

    /// <summary>Jenkins hash of the archetype name. The identity used to resolve the model.</summary>
    public int ArchetypeHash;

    /// <summary>Archetype name, for display and for files loaded where the archetype is unknown.</summary>
    public string ArchetypeName = "";

    [ObservableProperty]
    private int _layerId;

    [ObservableProperty]
    private Vector3 _position;

    [ObservableProperty]
    private Quaternion _rotation = Quaternion.Identity;

    /// <summary>Uniform scale. Non-uniform scale is not supported anywhere in the pipeline.</summary>
    [ObservableProperty]
    private float _scale = 1f;

    /// <summary>Optional user label shown in the Outliner instead of the archetype name.</summary>
    [ObservableProperty]
    private string? _name;

    /// <summary>ymap entity flags; copied from the archetype at placement, kept for export later.</summary>
    public uint Flags = 0x20;

    /// <summary>ymap lodDist; copied from the archetype record at placement, kept for export later.</summary>
    public float LodDist;

    // ---- CEntityDef round-trip fidelity ------------------------------------------------------
    //
    // Every default below is what YmapWriter emits for a prop this editor places, so an authored
    // entity is byte-identical to what it has always been. They exist because an IMPORTED entity
    // carries its own values and writing ours over the top is silent content loss: MEASURED
    // 27/08/2026, guid is non-zero in ALL 6,348 vanilla ymaps that have entities, lodLevel is not
    // ORPHANHD in 5,257, parentIndex is not -1 in 5,168.
    //
    // Not [ObservableProperty]: nothing in the UI edits them yet. Ruling 2 wants editors for the
    // map-level extras (car generators, occluders, LOD lights); these are per-entity plumbing that
    // has to survive a round trip first.

    /// <summary>CEntityDef.guid - a script handle. 0 for a freshly placed prop.</summary>
    public uint Guid;

    /// <summary>
    /// CEntityDef.scaleZ, kept apart from <see cref="Scale"/> because a ymap can carry NON-UNIFORM
    /// scale (2,479 vanilla files do) and <see cref="Scale"/> is uniform by contract - it is what
    /// the gizmo drags and what <see cref="World"/> renders. On import <see cref="Scale"/> takes
    /// scaleXY and this takes scaleZ; they are equal for everything else.
    /// </summary>
    public float ScaleZ = 1f;

    /// <summary>
    /// The ENTITY ID of this entity's LOD parent, or 0 for none.
    /// </summary>
    /// <remarks>
    /// The file stores an INDEX into its own entities array. An index cannot survive editing -
    /// delete one entity and every later index silently means a different prop - so import resolves
    /// it to a stable id and export converts it back. That is also why numChildren is DERIVED at
    /// export rather than stored: a stored count is a second source of truth that a single deletion
    /// makes wrong.
    /// </remarks>
    public int ParentEntityId;

    /// <summary>CEntityDef.childLodDist - the distance at which this entity's LOD children take over.</summary>
    public float ChildLodDist;

    /// <summary>CEntityDef.lodLevel as its enum VALUE. Default is ORPHANHD: not in a LOD hierarchy.</summary>
    public int LodLevel = YmapWriter.LodLevelOrphanHd;

    /// <summary>CEntityDef.priorityLevel as its enum value. Default PRI_REQUIRED.</summary>
    public int PriorityLevel = YmapWriter.PriorityRequired;

    /// <summary>CEntityDef.ambientOcclusionMultiplier. Vanilla default 255.</summary>
    public int AmbientOcclusionMultiplier = YmapWriter.DefaultAmbientOcclusionMultiplier;

    /// <summary>CEntityDef.artificialAmbientOcclusion. Vanilla default 128.</summary>
    public int ArtificialAmbientOcclusion = YmapWriter.DefaultArtificialAmbientOcclusionValue;

    /// <summary>CEntityDef.tintValue - an index into the archetype's tint palette.</summary>
    public uint TintValue;

    /// <summary>
    /// World matrix: scale, then rotation, then translation, composed left to right because
    /// System.Numerics is row-vector - the same ORDER as <c>Region.Flatten</c>.
    ///
    /// The quaternion convention is NOT the same as Flatten's, and the difference matters.
    /// Flatten renders a vanilla entity from <c>new Quaternion(x, y, z, -w)</c> because a ymap
    /// stores the conjugate of the rotation the world applies. Here <c>Rotation</c> is used as-is,
    /// so a project entity's rotation is in RENDER convention - what the mapper sees. Anything
    /// writing one back out to a ymap has to conjugate it; see
    /// <c>ExportService.ToYmapRotation</c>.
    /// </summary>
    public Matrix4x4 World =>
        Matrix4x4.CreateScale(Scale) *
        Matrix4x4.CreateFromQuaternion(Rotation) *
        Matrix4x4.CreateTranslation(Position);
}

