using System.Numerics;
using System.Text.Json;
using DinoEditor.Formats;
using DinoEditor.Formats.Ymap;

namespace DinoEditor.App.Projects;

/// <summary>Vector serialised as named components rather than an array, so a .dinoproj stays readable.</summary>
public sealed class Vec3Dto
{
    public float X { get; set; }
    public float Y { get; set; }
    public float Z { get; set; }
}

/// <summary>Rotation quaternion, named components for the same reason as <see cref="Vec3Dto"/>.</summary>
public sealed class QuatDto
{
    public float X { get; set; }
    public float Y { get; set; }
    public float Z { get; set; }
    public float W { get; set; } = 1f;
}

public sealed class LayerDto
{
    public int Id { get; set; }
    public string Name { get; set; } = "Layer";
    public bool Visible { get; set; } = true;
    public bool Locked { get; set; }
}

public sealed class EntityDto
{
    public int Id { get; set; }
    public int ArchetypeHash { get; set; }
    public string ArchetypeName { get; set; } = "";
    public int LayerId { get; set; }
    public Vec3Dto Position { get; set; } = new();
    public QuatDto Rotation { get; set; } = new();
    public float Scale { get; set; } = 1f;
    public string? Name { get; set; }
    public uint Flags { get; set; } = 0x20;
    public float LodDist { get; set; }
    public uint Guid { get; set; }
    public float ScaleZ { get; set; } = 1f;
    public int ParentEntityId { get; set; }
    public float ChildLodDist { get; set; }
    public int LodLevel { get; set; } = YmapWriter.LodLevelOrphanHd;
    public int PriorityLevel { get; set; } = YmapWriter.PriorityRequired;
    public int AmbientOcclusionMultiplier { get; set; } = YmapWriter.DefaultAmbientOcclusionMultiplier;
    public int ArtificialAmbientOcclusion { get; set; } = YmapWriter.DefaultArtificialAmbientOcclusionValue;
    public uint TintValue { get; set; }
}

/// <summary>
/// One <see cref="MapDocument"/> as written to disk: its own metadata plus the layers and entities
/// that belong to it. Introduced in format version 2 - a version 1 file has no <c>Maps</c> array at
/// all and is upgraded into a single one of these on load.
/// </summary>
public sealed class MapDto
{
    public int Id { get; set; }
    public string Name { get; set; } = "Map";
    public bool Visible { get; set; } = true;
    public MapOrigin Origin { get; set; } = MapOrigin.Authored;
    public string? SourcePath { get; set; }
    public int SourceNameHash { get; set; }
    public int SourceParentHash { get; set; }
    public uint SourceFlags { get; set; }
    public uint SourceContentFlags { get; set; }
    public YmapBlocks UnsupportedBlocks { get; set; }
    public int UnconvertedEntityCount { get; set; }
    public List<string> OverrideIgnoredByPacks { get; set; } = new();

    /// <summary>Null in projects written before Drop 10; coalesced on read.</summary>
    public List<uint>? PhysicsDictionaries { get; set; } = new();

    /// <summary>Null in projects written before Drop 13; coalesced on read. System.Text.Json
    /// serializes byte[] as base64 natively, so no converter attribute is needed.</summary>
    public byte[]? CarGensData { get; set; } = Array.Empty<byte>();
    public int CarGenCount { get; set; }

    /// <summary>Null in projects written before Drop 13; coalesced on read.</summary>
    public byte[]? TimeCyclesData { get; set; } = Array.Empty<byte>();
    public int TimeCycleCount { get; set; }

    /// <summary>Null in every project written before this field existed, which is why the reader
    /// coalesces it - an older file simply has no record of whether the scan was complete.</summary>
    public List<string>? OverrideCheckUnreadablePacks { get; set; } = new();

    /// <summary>
    /// Null in every project written before Drop 11, and the reader must NOT read that null as
    /// false - see <see cref="ProjectFile"/>'s loader.
    /// </summary>
    public bool? OverrideShippedByBaseGame { get; set; }

    /// <summary>Null in every project written before Drop 11; coalesced on read.</summary>
    public List<string>? OverrideCheckUnscannedArchives { get; set; } = new();
    public bool NameIsExplicit { get; set; }
    public bool AutoPartition { get; set; } = true;
    public List<LayerDto> Layers { get; set; } = new();
    public List<EntityDto> Entities { get; set; } = new();
}

/// <summary>
/// The on-disk shape of a project and the only code that reads or writes a <c>.dinoproj</c>.
/// </summary>
/// <remarks>
/// Two rules drive the design. Writes are crash-safe: the JSON goes to <c>&lt;path&gt;.tmp</c> first
/// and is moved over the real file only once it is complete, so a power cut can never leave a
/// half-written project where a good one used to be. Reads never throw: a missing, empty, corrupt
/// or future-version file comes back as an error string the UI shows, because a bad file on disk
/// must not be able to take the editor down.
/// </remarks>
public sealed class ProjectFile
{
    /// <summary>
    /// The version this build writes. It also reads version 1 (upgrading it on the way in) and
    /// refuses anything newer, but never guesses at a shape it does not recognise.
    /// </summary>
    public const int CurrentFormatVersion = 2;

    private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    public int FormatVersion { get; set; } = CurrentFormatVersion;
    public string Name { get; set; } = "Untitled";
    public int ActiveMapId { get; set; }
    public int ActiveLayerId { get; set; }
    public int NextId { get; set; } = 1;
    public Vec3Dto? CameraPosition { get; set; }
    public float CameraYaw { get; set; }
    public float CameraPitch { get; set; }
    public List<MapDto> Maps { get; set; } = new();

    /// <summary>
    /// The version 1 shape: layers and entities flat at the project root, with no notion of a map.
    /// Populated only by a version 1 file on disk, and read only by <see cref="ToProjectFromV1"/>.
    /// </summary>
    public List<LayerDto> Layers { get; set; } = new();

    /// <summary>The version 1 shape's entities. See <see cref="Layers"/>.</summary>
    public List<EntityDto> Entities { get; set; } = new();

    /// <summary>
    /// The project as the JSON text that would be written for it. Used by the tests as an exact
    /// equality check ("undo restored the project") and available to callers that want to compare
    /// two project states without walking the object graph.
    /// </summary>
    public static string Snapshot(Project project) => JsonSerializer.Serialize(From(project), JsonOptions);

    public static ProjectFile From(Project project)
    {
        var file = new ProjectFile
        {
            FormatVersion = CurrentFormatVersion,
            Name = project.Name,
            ActiveMapId = project.ActiveMapId,
            ActiveLayerId = project.ActiveLayerId,
            NextId = project.NextId,
            CameraYaw = project.CameraYaw,
            CameraPitch = project.CameraPitch,
            CameraPosition = project.CameraPosition is { } c ? new Vec3Dto { X = c.X, Y = c.Y, Z = c.Z } : null,
        };

        foreach (var map in project.Maps)
        {
            var mapDto = new MapDto
            {
                Id = map.Id,
                Name = map.Name,
                Visible = map.Visible,
                Origin = map.Origin,
                SourcePath = map.SourcePath,
                SourceNameHash = map.SourceNameHash,
                SourceParentHash = map.SourceParentHash,
                SourceFlags = map.SourceFlags,
                SourceContentFlags = map.SourceContentFlags,
                UnsupportedBlocks = map.UnsupportedBlocks,
                UnconvertedEntityCount = map.UnconvertedEntityCount,
                OverrideIgnoredByPacks = new List<string>(map.OverrideIgnoredByPacks),
                PhysicsDictionaries = new List<uint>(map.PhysicsDictionaries),
                CarGensData = map.CarGensData,
                CarGenCount = map.CarGenCount,
                TimeCyclesData = map.TimeCyclesData,
                TimeCycleCount = map.TimeCycleCount,
                OverrideCheckUnreadablePacks = new List<string>(map.OverrideCheckUnreadablePacks),
                OverrideShippedByBaseGame = map.OverrideShippedByBaseGame,
                OverrideCheckUnscannedArchives = new List<string>(map.OverrideCheckUnscannedArchives),
                NameIsExplicit = map.NameIsExplicit,
                AutoPartition = map.AutoPartition,
            };

            foreach (var layer in map.Layers)
            {
                mapDto.Layers.Add(new LayerDto
                {
                    Id = layer.Id,
                    Name = layer.Name,
                    Visible = layer.Visible,
                    Locked = layer.Locked,
                });
            }

            foreach (var entity in map.Entities)
            {
                mapDto.Entities.Add(new EntityDto
                {
                    Id = entity.Id,
                    ArchetypeHash = entity.ArchetypeHash,
                    ArchetypeName = entity.ArchetypeName,
                    LayerId = entity.LayerId,
                    Position = new Vec3Dto { X = entity.Position.X, Y = entity.Position.Y, Z = entity.Position.Z },
                    Rotation = new QuatDto
                    {
                        X = entity.Rotation.X,
                        Y = entity.Rotation.Y,
                        Z = entity.Rotation.Z,
                        W = entity.Rotation.W,
                    },
                    Scale = entity.Scale,
                    Name = entity.Name,
                    Flags = entity.Flags,
                    LodDist = entity.LodDist,
                    Guid = entity.Guid,
                    ScaleZ = entity.ScaleZ,
                    ParentEntityId = entity.ParentEntityId,
                    ChildLodDist = entity.ChildLodDist,
                    LodLevel = entity.LodLevel,
                    PriorityLevel = entity.PriorityLevel,
                    AmbientOcclusionMultiplier = entity.AmbientOcclusionMultiplier,
                    ArtificialAmbientOcclusion = entity.ArtificialAmbientOcclusion,
                    TintValue = entity.TintValue,
                });
            }

            file.Maps.Add(mapDto);
        }

        return file;
    }

    private static Layer LayerFromDto(LayerDto dto) => new()
    {
        Id = dto.Id,
        Name = dto.Name,
        Visible = dto.Visible,
        Locked = dto.Locked,
    };

    private static ProjectEntity EntityFromDto(EntityDto dto) => new()
    {
        Id = dto.Id,
        ArchetypeHash = dto.ArchetypeHash,
        ArchetypeName = dto.ArchetypeName,
        LayerId = dto.LayerId,
        Position = new Vector3(dto.Position.X, dto.Position.Y, dto.Position.Z),
        Rotation = new Quaternion(dto.Rotation.X, dto.Rotation.Y, dto.Rotation.Z, dto.Rotation.W),
        Scale = dto.Scale,
        Name = dto.Name,
        Flags = dto.Flags,
        LodDist = dto.LodDist,
        Guid = dto.Guid,
        ScaleZ = dto.ScaleZ,
        ParentEntityId = dto.ParentEntityId,
        ChildLodDist = dto.ChildLodDist,
        LodLevel = dto.LodLevel,
        PriorityLevel = dto.PriorityLevel,
        AmbientOcclusionMultiplier = dto.AmbientOcclusionMultiplier,
        ArtificialAmbientOcclusion = dto.ArtificialAmbientOcclusion,
        TintValue = dto.TintValue,
    };

    /// <summary>
    /// Repairs applied on load, run PER MAP. An entity or a missing layer belongs to the map it was
    /// found in - running this once globally across all maps would let an orphaned entity in one map
    /// get adopted into another map's first layer, which silently moves a prop between the ymaps the
    /// two maps export to.
    /// </summary>
    private static void RepairMap(MapDocument map, ref int nextId)
    {
        // A map with no layer at all cannot be edited (there is nowhere to place into), and a file
        // can arrive that way only if it was hand-edited. Repair it rather than refuse it.
        if (map.Layers.Count == 0)
        {
            map.Layers.Add(new Layer { Id = nextId++, Name = "Layer 1" });
        }

        // An entity pointing at a layer that does not exist IN THIS MAP is invisible twice over - the
        // entity source skips it and the Outliner never lists it - yet it is still written back out
        // on the next save. Adopt it into this map's first layer so it can be seen and edited.
        foreach (var entity in map.Entities)
        {
            bool found = false;
            foreach (var layer in map.Layers)
            {
                if (layer.Id == entity.LayerId) { found = true; break; }
            }

            if (!found) entity.LayerId = map.Layers[0].Id;
        }
    }

    public Project ToProject()
    {
        var project = new Project
        {
            Name = Name,
            ActiveMapId = ActiveMapId,
            ActiveLayerId = ActiveLayerId,
            NextId = NextId,
            CameraYaw = CameraYaw,
            CameraPitch = CameraPitch,
            CameraPosition = CameraPosition is { } c ? new Vector3(c.X, c.Y, c.Z) : null,
        };

        foreach (var mapDto in Maps)
        {
            var map = new MapDocument
            {
                Id = mapDto.Id,
                Name = mapDto.Name,
                Visible = mapDto.Visible,
                Origin = mapDto.Origin,
                SourcePath = mapDto.SourcePath,
                SourceNameHash = mapDto.SourceNameHash,
                SourceParentHash = mapDto.SourceParentHash,
                SourceFlags = mapDto.SourceFlags,
                SourceContentFlags = mapDto.SourceContentFlags,
                UnsupportedBlocks = mapDto.UnsupportedBlocks,
                UnconvertedEntityCount = mapDto.UnconvertedEntityCount,
                OverrideIgnoredByPacks = new List<string>(mapDto.OverrideIgnoredByPacks ?? new List<string>()),
                PhysicsDictionaries = new List<uint>(mapDto.PhysicsDictionaries ?? new List<uint>()),
                CarGensData = mapDto.CarGensData ?? Array.Empty<byte>(),
                CarGenCount = mapDto.CarGenCount,
                TimeCyclesData = mapDto.TimeCyclesData ?? Array.Empty<byte>(),
                TimeCycleCount = mapDto.TimeCycleCount,
                OverrideCheckUnreadablePacks = new List<string>(mapDto.OverrideCheckUnreadablePacks ?? new List<string>()),
                // A PROJECT WRITTEN BEFORE DROP 11 HAS NO VERDICT, and reading that null as false
                // would silently UNBLOCK a map the old patchday gate refused - a safety regression
                // shipped as a migration. Those tiles were measured base-game in every case E1
                // covered, so a non-empty legacy pack list stands in for the verdict; the reader
                // fails toward keeping the refusal it already had, never toward inventing an
                // allowance from data that never recorded one.
                OverrideShippedByBaseGame = mapDto.OverrideShippedByBaseGame
                    ?? (mapDto.OverrideIgnoredByPacks is { Count: > 0 }),
                OverrideCheckUnscannedArchives = new List<string>(mapDto.OverrideCheckUnscannedArchives ?? new List<string>()),
                NameIsExplicit = mapDto.NameIsExplicit,
                AutoPartition = mapDto.AutoPartition,
            };

            foreach (var dto in mapDto.Layers) map.Layers.Add(LayerFromDto(dto));
            foreach (var dto in mapDto.Entities) map.Entities.Add(EntityFromDto(dto));

            project.Maps.Add(map);
        }

        FinishRepairs(project);
        return project;
    }

    /// <summary>
    /// Upgrades a version 1 file - layers and entities flat at the project root - into a version 2
    /// project: exactly one <see cref="MapDocument"/>, Authored, auto-partitioning, holding what used
    /// to be the whole project.
    /// </summary>
    private Project ToProjectFromV1()
    {
        var project = new Project
        {
            Name = Name,
            ActiveLayerId = ActiveLayerId,
            NextId = NextId,
            CameraYaw = CameraYaw,
            CameraPitch = CameraPitch,
            CameraPosition = CameraPosition is { } c ? new Vector3(c.X, c.Y, c.Z) : null,
        };

        var map = new MapDocument
        {
            Id = project.NextId++,
            // The project's own display name, not a sanitized form of it: a map NAME is a
            // display name and ExportService sanitizes it when it becomes a file name. The
            // sole-authored-map invariant in FinishRepairs sets this anyway; it is spelled out
            // here so the two paths do not appear to disagree.
            Name = Name,
            Visible = true,
            Origin = MapOrigin.Authored,
            AutoPartition = true,
        };

        foreach (var dto in Layers) map.Layers.Add(LayerFromDto(dto));
        foreach (var dto in Entities) map.Entities.Add(EntityFromDto(dto));

        project.Maps.Add(map);
        project.ActiveMapId = map.Id;

        FinishRepairs(project);
        return project;
    }

    /// <summary>
    /// Repairs shared by both load paths, applied after every map has been built: a project with no
    /// map at all gets one, <see cref="Project.ActiveMapId"/> and <see cref="Project.ActiveLayerId"/>
    /// are pointed at something that actually exists, ids are pushed past everything on disk, and
    /// then each map's own layer/orphan repairs run (see <see cref="RepairMap"/>).
    /// </summary>
    private static void FinishRepairs(Project project)
    {
        int nextId = project.NextId;

        if (project.Maps.Count == 0)
        {
            project.Maps.Add(new MapDocument { Id = nextId++, Name = project.Name, Visible = true, Origin = MapOrigin.Authored, AutoPartition = true });
        }

        // INTERIM INVARIANT, same one ProjectService.SoleAuthoredMap enforces on rename: a
        // project's sole authored map is named after the project. Since Drop 7 the exported ymap is
        // named after the MAP, and nothing in the editor can rename a map, so a map name is never a
        // mapper choice. Without this repair a v2 .dinoproj saved before that rule existed - map
        // "Untitled" next to a project "Downtown Core" - would export "untitled.ymap" forever, with
        // no way to correct it from inside the editor. DELETE THIS the moment a map list can rename
        // a map.
        if (project.Maps.Count == 1 && project.Maps[0].Origin == MapOrigin.Authored
            && !project.Maps[0].NameIsExplicit)
            project.Maps[0].Name = project.Name;

        foreach (var map in project.Maps) RepairMap(map, ref nextId);

        // IDS ALREADY DUPLICATED ON DISK are repaired here. Pushing NextId past maxId below only
        // fixes the FUTURE case - the next Place minting a colliding id - and does nothing about a
        // file that already contains the collision. A hand-edited or merged .dinoproj can, and the
        // damage is silent: everything downstream resolves by id through FindMap / FindEntity,
        // which return the FIRST match, so the Outliner acts on the wrong map and export throws a
        // raw framework error after stream/ has already been created.
        //
        // Maps, layers and entities share ONE id counter, so they are deduplicated against one
        // shared set rather than three.
        //
        // THE LATER OCCURRENCE IS ALWAYS THE ONE REMINTED, never the first. Every reference that
        // survives a load - ActiveMapId, ActiveLayerId, an entity's LayerId - resolves to the first
        // match today, so leaving the first id untouched keeps all of them pointing at the same
        // object they pointed at before the repair. Reminting the first would silently redirect
        // them instead.
        var seen = new HashSet<int>();
        foreach (var map in project.Maps)
        {
            if (!seen.Add(map.Id)) map.Id = nextId++;
            foreach (var layer in map.Layers)
            {
                if (seen.Add(layer.Id)) continue;

                // An entity's LayerId is a reference, so it moves with the layer - but only for
                // entities in THIS map, and only where the map has no other layer already carrying
                // the old id. When it does, the reference is genuinely ambiguous and is left alone
                // to resolve to that first layer, which is where it resolved before.
                int old = layer.Id;
                layer.Id = nextId++;
                bool anotherLayerKeepsTheOldId = false;
                foreach (var other in map.Layers)
                {
                    if (!ReferenceEquals(other, layer) && other.Id == old) { anotherLayerKeepsTheOldId = true; break; }
                }

                if (!anotherLayerKeepsTheOldId)
                    foreach (var entity in map.Entities)
                        if (entity.LayerId == old) entity.LayerId = layer.Id;
            }

            foreach (var entity in map.Entities)
                if (!seen.Add(entity.Id)) entity.Id = nextId++;
        }

        bool activeMapExists = false;
        foreach (var map in project.Maps)
        {
            if (map.Id == project.ActiveMapId) { activeMapExists = true; break; }
        }

        if (!activeMapExists) project.ActiveMapId = project.Maps[0].Id;

        // Checked against the ACTIVE map's own layers, not the whole project: ActiveLayerId names
        // where new entities are placed within ActiveMap, so a stale id must fall back to a layer of
        // THAT map, never to a layer that merely happens to exist somewhere else.
        bool activeLayerExists = false;
        foreach (var layer in project.ActiveMap.Layers)
        {
            if (layer.Id == project.ActiveLayerId) { activeLayerExists = true; break; }
        }

        if (!activeLayerExists) project.ActiveLayerId = project.ActiveMap.Layers[0].Id;

        // NextId at or below an id already in use would make the next Place mint a DUPLICATE id, and
        // everything downstream (selection, gizmo, Details, Delete) resolves an entity by id through
        // Project.FindEntity, which returns the first match - so the editor would silently act on
        // the wrong one of the pair. Push NextId past everything the file actually contains, maps
        // included since map ids are minted from the same counter.
        int maxId = 0;
        foreach (var map in project.Maps)
        {
            maxId = Math.Max(maxId, map.Id);
            foreach (var layer in map.Layers) maxId = Math.Max(maxId, layer.Id);
            foreach (var entity in map.Entities) maxId = Math.Max(maxId, entity.Id);
        }

        project.NextId = Math.Max(nextId, maxId + 1);
    }

    /// <summary>
    /// Writes the project to <paramref name="path"/> through a temporary file. Returns the failure
    /// rather than throwing: the caller shows it, and the previous file on disk stays intact.
    /// </summary>
    public static (bool ok, string? error) Save(string path, Project project)
    {
        var tmp = path + ".tmp";
        try
        {
            var dir = System.IO.Path.GetDirectoryName(path);
            if (!string.IsNullOrEmpty(dir)) Directory.CreateDirectory(dir);

            File.WriteAllText(tmp, JsonSerializer.Serialize(From(project), JsonOptions));
            File.Move(tmp, path, overwrite: true);
            return (true, null);
        }
        catch (Exception ex)
        {
            TryDelete(tmp);
            return (false, ex.Message);
        }
    }

    /// <summary>
    /// Reads a project. Never throws: a missing, empty, corrupt or unsupported-version file returns
    /// (null, message).
    /// </summary>
    public static (Project? project, string? error) Load(string path)
    {
        try
        {
            if (!File.Exists(path)) return (null, $"Project file not found: {path}");

            var json = File.ReadAllText(path);
            if (string.IsNullOrWhiteSpace(json)) return (null, $"Project file is empty: {path}");

            var file = JsonSerializer.Deserialize<ProjectFile>(json, JsonOptions);
            if (file == null) return (null, $"Project file could not be read: {path}");

            if (file.FormatVersion == CurrentFormatVersion) return (file.ToProject(), null);
            if (file.FormatVersion == 1) return (file.ToProjectFromV1(), null);

            return (null,
                $"Unsupported project format version {file.FormatVersion} (this build reads version {CurrentFormatVersion}).");
        }
        catch (Exception ex)
        {
            return (null, ex.Message);
        }
    }

    private static void TryDelete(string path)
    {
        try { if (File.Exists(path)) File.Delete(path); }
        catch (IOException) { }
        catch (UnauthorizedAccessException) { }
    }
}

