using System.Text;

namespace DinoEditor.App.Projects;

/// <summary>
/// Turns a display name into the single string that has to serve as a ymap's file name, its
/// <c>CMapData.name</c> and the joaat hash the engine resolves it by.
/// </summary>
/// <remarks>
/// This lived on <c>ExportService</c> (in <c>Services/</c>) and was called from
/// <c>ProjectFile</c> (in <c>Project/</c>) while <c>Services</c> already depended on
/// <c>Project</c> - a cycle between the two folders for the sake of one pure string function.
/// It sits in <c>Project/</c> rather than next to <c>Services/PathGuard.cs</c> for exactly that
/// reason: the dependency only points one way from here.
/// </remarks>
public static class ResourceName
{
    /// <summary>Used when a name sanitizes down to nothing.</summary>
    public const string Fallback = "dinoexport";

    /// <summary>
    /// The name's lowercased, file-safe form. Lowercased because file and asset hashes in RAGE are
    /// lowercased, so the file name and the hash written inside it must agree character for
    /// character or the engine resolves the resource under a name nothing registered.
    /// </summary>
    public static string Sanitize(string? name)
    {
        if (string.IsNullOrWhiteSpace(name)) return Fallback;

        var sb = new StringBuilder(name.Length);
        foreach (char c in name.Trim().ToLowerInvariant())
        {
            if (c is (>= 'a' and <= 'z') or (>= '0' and <= '9')) sb.Append(c);
            else if (c is '_' or '-') sb.Append(c);
            else if (char.IsWhiteSpace(c)) sb.Append('_');
        }

        string sanitized = sb.ToString().Trim('_');
        return sanitized.Length == 0 ? Fallback : sanitized;
    }
}

