using System.Numerics;
using DinoEditor.Formats;
using DinoEditor.Formats.Ymap;

namespace DinoEditor.App.Projects;

/// <summary>
/// CEntityDef content a source ymap carried that this editor still cannot write back, and which
/// would therefore be silently changed by an export.
/// </summary>
/// <remarks>
/// This list used to be much longer. As of Drop 7 guid, scaleXY/scaleZ, parentIndex, childLodDist,
/// numChildren, tintValue and both ambient-occlusion values are all carried through a round trip -
/// they had to be, because MEASURED across the whole vanilla install, guid alone is non-zero in ALL
/// 6,348 ymaps that have entities, so refusing them would have refused every real file.
///
/// What is left is the case where the file names an enum member this writer has no value for.
/// Measured across 7,572 vanilla and 94 FiveM ymaps, no real file does: the only lodLevel values
/// that occur are HD, LOD, SLOD1, SLOD2, SLOD3 and ORPHANHD, and the only priorityLevel values are
/// the four PRI_* names, all of which are in YmapWriter's enum tables. So this exists to fail
/// closed on a format variant we have not seen, not to catch something common.
/// </remarks>
[Flags]
public enum EntityFields
{
    None = 0,

    /// <summary>A lodLevel name with no value in YmapWriter's enum table.</summary>
    LodLevel = 1 << 0,

    /// <summary>A priorityLevel name with no value in YmapWriter's enum table.</summary>
    PriorityLevel = 1 << 1,
}

/// <summary>Names for <see cref="EntityFields"/>, in the ymap's own spelling.</summary>
public static class EntityFieldNames
{
    private static readonly (EntityFields Bit, string Name)[] All =
    {
        (EntityFields.LodLevel, "lodLevel"),
        (EntityFields.PriorityLevel, "priorityLevel"),
    };

    public static IReadOnlyList<string> Of(EntityFields fields)
    {
        var names = new List<string>();
        foreach (var (bit, name) in All)
        {
            if ((fields & bit) != 0) names.Add(name);
        }

        return names;
    }

    public static string Join(EntityFields fields) => string.Join(", ", Of(fields));
}

/// <summary>What reading one ymap into the project produced.</summary>
/// <param name="Map">The map document, ready to be added to a project.</param>
/// <param name="EntitiesRead">CEntityDef entities converted into project entities.</param>
/// <param name="Fields">CEntityDef fields the source set and this editor cannot write back.</param>
public sealed record YmapImportResult(MapDocument Map, int EntitiesRead, EntityFields Fields);

/// <summary>
/// Turns a parsed <see cref="YmapRecord"/> into a <see cref="MapDocument"/> the project can hold.
///
/// Pure: it allocates ids and resolves archetype names through the two delegates it is given and
/// touches nothing else, so it is testable without a loaded GTA install.
/// </summary>
public static class YmapImport
{
    /// <summary>The single layer an imported map starts with. Imported content arrives flat -
    /// a ymap has no layer concept - and the mapper can split it up afterwards.</summary>
    public const string DefaultLayerName = "Imported";

    /// <summary>The entity struct this editor can represent. Anything else - a CMloInstanceDef
    /// (an interior placement) or a struct this reader does not know - is counted, not imported.</summary>
    public const string SupportedEntityKind = "CEntityDef";

    /// <summary>
    /// Builds the map document. <paramref name="nextId"/> hands out ids from the project's own
    /// counter; <paramref name="resolveName"/> turns an archetype hash into a display name and may
    /// return an empty string when this install does not have that archetype - which is not an
    /// error, only a name the outliner will not show.
    /// </summary>
    /// <param name="overrideIgnoredBy">
    /// Given the tile's own name, the <c>patchday*</c> packs that re-ship it - i.e. the reason a
    /// same-named override would be silently ignored in game (E1). Only consulted for
    /// <see cref="MapOrigin.ImportedVanilla"/>: a map resource of the mapper's own is not replacing
    /// a base-game tile. Null means "not checked", which imports permissively.
    /// </param>
    public static YmapImportResult Build(
        YmapRecord record,
        MapOrigin origin,
        Func<int> nextId,
        Func<int, string> resolveName,
        Func<string, OverrideCheck>? overrideIgnoredBy = null)
    {
        var map = new MapDocument
        {
            Id = nextId(),
            Name = BaseName(record.File),
            Visible = true,
            Origin = origin,
            SourcePath = record.File,
            SourceNameHash = record.NameHash,
            SourceParentHash = record.ParentHash,
            SourceFlags = record.Flags,
            SourceContentFlags = record.ContentFlags,
            // An imported map REPLACES the file it came from, so it must stay one file under one
            // name. See ExportService's pinned/free split.
            AutoPartition = false,
            UnsupportedBlocks = record.UnsupportedBlocks,
            // Carried verbatim so a re-export reproduces the source's physics dictionaries. The
            // hashes are opaque: nothing here resolves or validates a name.
            PhysicsDictionaries = new List<uint>(record.PhysicsDictionaries),
            // Carried verbatim so a re-export reproduces the source's car generators and time
            // cycle modifiers. Opaque bytes: nothing here interprets them.
            CarGensData = record.CarGensData,
            CarGenCount = record.CarGenCount,
            TimeCyclesData = record.TimeCyclesData,
            TimeCycleCount = record.TimeCycleCount,
        };

        // E1: replacing a vanilla tile only works when the BASE GAME does not ship it. Resolved
        // HERE, at import, while the install is loaded - the answer is persisted with the map
        // because it is not necessarily obtainable when the mapper finally exports.
        if (origin == MapOrigin.ImportedVanilla && overrideIgnoredBy != null)
        {
            var check = overrideIgnoredBy(map.Name);
            map.OverrideShippedByBaseGame = check.ShippedByBaseGame;
            // Recorded even when the verdict is TRUE. A true verdict needs no scan caveat - the
            // name was seen in an x64 archive - but persisting the caveat unconditionally keeps
            // the two fields honest as a pair, and costs an empty list.
            map.OverrideCheckUnscannedArchives.AddRange(check.UnscannedArchives);

            // Information now, not the gate. Kept because the packs correlate with real DLC
            // behaviour and the mapper may want to know; nothing refuses on them.
            map.OverrideIgnoredByPacks.AddRange(check.ShippingPacks);
            // Kept even when ShippingPacks is non-empty: an incomplete scan means the LIST OF PACKS
            // is partial too, and a partial list reads as a complete one unless it says otherwise.
            map.OverrideCheckUnreadablePacks.AddRange(check.UnreadablePacks);
        }

        var layer = new Layer { Id = nextId(), Name = DefaultLayerName };
        map.Layers.Add(layer);

        var fields = EntityFields.None;
        int unconverted = 0;

        // The file's parentIndex is an index into its OWN entities array, so a map from source
        // index to the id we hand out has to be built as we go. It is keyed on the source index
        // rather than on our position because an entity we skip (an MLO instance) would otherwise
        // shift every later index by one and silently re-parent the rest of the file.
        var idBySourceIndex = new Dictionary<int, int>(record.Entities.Count);
        var parentIndexById = new Dictionary<int, int>();

        for (int i = 0; i < record.Entities.Count; i++)
        {
            var e = record.Entities[i];
            if (e.Kind != SupportedEntityKind) { unconverted++; continue; }

            fields |= FieldsLost(e);

            int id = nextId();
            idBySourceIndex[i] = id;
            if (e.ParentIndex >= 0) parentIndexById[id] = e.ParentIndex;

            map.Entities.Add(new ProjectEntity
            {
                Id = id,
                ArchetypeHash = e.ArchetypeNameHash,
                ArchetypeName = resolveName(e.ArchetypeNameHash),
                LayerId = layer.Id,
                Position = e.Position,
                Rotation = ToRenderRotation(e.Rotation),
                Scale = e.ScaleXY > 0f ? e.ScaleXY : 1f,
                ScaleZ = e.ScaleZ > 0f ? e.ScaleZ : 1f,
                Flags = e.Flags,
                LodDist = e.LodDist,
                Guid = e.Guid,
                ChildLodDist = e.ChildLodDist,
                LodLevel = LodLevelValue(e.LodLevel),
                PriorityLevel = PriorityLevelValue(e.PriorityLevel),
                AmbientOcclusionMultiplier = (int)MathF.Round(e.AmbientOcclusionMultiplier),
                ArtificialAmbientOcclusion = (int)MathF.Round(e.ArtificialAmbientOcclusion),
                TintValue = (uint)MathF.Max(MathF.Round(e.TintValue), 0f),
            });
        }

        // Second pass: an entity can name a parent that appears LATER in the file, so ids are only
        // all known now. A parentIndex pointing at an entity we did not import (an MLO instance) or
        // outside the array resolves to no parent rather than to the wrong one - the map is a hard
        // export failure in that case anyway, because unconverted > 0.
        foreach (var entity in map.Entities)
        {
            if (!parentIndexById.TryGetValue(entity.Id, out int sourceIndex)) continue;
            if (idBySourceIndex.TryGetValue(sourceIndex, out int parentId) && parentId != entity.Id)
                entity.ParentEntityId = parentId;
        }

        map.UnconvertedEntityCount = unconverted;
        return new YmapImportResult(map, map.Entities.Count, fields);
    }

    /// <summary>
    /// A ymap stores the CONJUGATE of the rotation the world applies, and
    /// <see cref="ProjectEntity.Rotation"/> is in RENDER convention - what the mapper sees in the
    /// viewport. So reading is the exact inverse of <c>ExportService.ToYmapRotation</c>, which
    /// conjugates on the way out. Getting this backwards mirrors every imported prop about its own
    /// axis, and is invisible at 0 and 180 degrees - the same trap that let the export bug ship
    /// once already.
    /// </summary>
    public static Quaternion ToRenderRotation(Vector4 stored)
    {
        var q = new Quaternion(stored.X, stored.Y, stored.Z, stored.W);
        // A hand-authored or tool-written ymap can hold a drifted quaternion; normalising here is
        // what stops it reaching the gizmo as a skew.
        float len = q.Length();
        return Quaternion.Conjugate(len > 1e-6f ? Quaternion.Normalize(q) : Quaternion.Identity);
    }

    /// <summary>The lodLevel enum value behind the name the reader resolved. An unrecognised name
    /// falls back to ORPHANHD - the value for "not in a LOD hierarchy" - and is reported through
    /// <see cref="EntityFields.LodLevel"/> so it is never silently swallowed.</summary>
    private static int LodLevelValue(string name) =>
        YmapWriter.TryLodLevelValue(name, out int value) ? value : YmapWriter.LodLevelOrphanHd;

    private static int PriorityLevelValue(string name) =>
        YmapWriter.TryPriorityLevelValue(name, out int value) ? value : YmapWriter.PriorityRequired;

    /// <summary>Which of this entity's fields still hold something the writer cannot reproduce.</summary>
    private static EntityFields FieldsLost(EntityRecord e)
    {
        var lost = EntityFields.None;
        // lodLevel and priorityLevel are now carried through, so only a name this writer has no
        // enum value for is a loss. Measured across both corpora, no real file has one.
        if (!YmapWriter.TryLodLevelValue(e.LodLevel, out _)) lost |= EntityFields.LodLevel;
        if (!YmapWriter.TryPriorityLevelValue(e.PriorityLevel, out _)) lost |= EntityFields.PriorityLevel;
        return lost;
    }

    /// <summary>
    /// The ymap's own name: the file's base name with the extension off. This is what the map is
    /// called and, for a pinned export, the file name it must be written back under - so it keeps
    /// the source spelling exactly and is never sanitized here.
    /// </summary>
    public static string BaseName(string path)
    {
        string leaf = path.Replace('\\', '/');
        int slash = leaf.LastIndexOf('/');
        if (slash >= 0) leaf = leaf[(slash + 1)..];
        if (leaf.EndsWith(".ymap", StringComparison.OrdinalIgnoreCase))
            leaf = leaf[..^".ymap".Length];
        return leaf;
    }
}

