namespace DinoEditor.App.Services;

/// <summary>Everything persisted to settings.json. Plain properties on purpose: this type is the
/// serialisation contract, the view models hold the observable copies.</summary>
public sealed class AppSettings
{
    public string? GameDir { get; set; }
    public string? CacheDir { get; set; }
    public string Language { get; set; } = "en";
    public bool ExcludeHeistYmaps { get; set; } = true;
    public float CameraSpeed { get; set; } = 20f;

    public double WindowWidth { get; set; } = 1600;
    public double WindowHeight { get; set; } = 900;

    /// <summary>The three splitters the user can actually drag in the Unreal-style shell: the width
    /// of the right column (Outliner + Details), the height of the bottom drawer (Content Drawer +
    /// Output Log), and the Outliner's share of the right column.</summary>
    public double RightPaneProportion { get; set; } = 0.22;
    public double BottomPaneProportion { get; set; } = 0.25;
    public double OutlinerProportion { get; set; } = 0.55;

    /// <summary>False when the user has closed the bottom drawer. Closing it removes the dock
    /// entirely and gives the row back to the viewport, the way Unreal's Content Drawer behaves;
    /// the status bar toggles are the way back.</summary>
    public bool DrawerVisible { get; set; } = true;

    /// <summary>Content Drawer thumbnail cell size in pixels; one of 96 / 128 / 192.</summary>
    public int ThumbnailCellSize { get; set; } = 128;

    /// <summary>Whether the Content Drawer shows LOD/SLOD pieces (auto-generated distant-view
    /// meshes, not placeable props). Off by default - see <c>CatalogSearch.Filters.HideLodPieces</c>.</summary>
    public bool BrowserShowLodPieces { get; set; } = false;

    /// <summary>Folder the last project was saved to or opened from; the file pickers start there
    /// instead of wherever Windows last left them. Null until a project file is chosen.</summary>
    public string? LastProjectDir { get; set; }

    /// <summary>Folder the last .ymap was imported from. Kept apart from
    /// <see cref="LastProjectDir"/> because they are different places: projects live in the
    /// mapper's own workspace, ymaps in a FiveM resource's stream/ folder somewhere else entirely.</summary>
    public string? LastImportDir { get; set; }

    public AppSettings Clone() => (AppSettings)MemberwiseClone();
}

