    if (/^\s+$/.test(trail) && /[\u3400-\u9fff，。、；：！？]$/.test(out) && cnNext) trail = "";
    // 译文自带句末标点、原句尾还挂着一个 "。" 的独立节点 → 吞掉，避免「肿瘤缩写。。」
    if (/[。！？，、；：]$/.test(out)) {
