      while (nxtNode && nxtNode.nodeType === 3 && !String(nxtNode.nodeValue || "").trim()) nxtNode = nxtNode.nextSibling;
      if (nxtNode && nxtNode.nodeType === 3 && /^[。．.！？]\s*$/.test(String(nxtNode.nodeValue || "").trim())) {
