  }

  /** SVG <text> 整块翻：tspan 会把 "Bone marrow" 拆成 "Bone " + "marrow"，
   *  逐节点翻就变成「骨marrow」。以整个 <text> 为单位查表，命中后写回第一个文本节点。 */
  var svgDone = new WeakSet();
