    if (!t) return false;
    if (svgDone.has(t)) return true;
    svgDone.add(t);
    // tspan 既可能在空格处断（"Bone " + "marrow"），也可能在词中间断（"Bone" + "marrow"），
    // 两种拼接都试一次，取命中的那个，避免出现 "Bonemarrow" 或 "骨marrow"。
    var cands = svgCandidates(t);
    var out = null, full = cands[0];
    for (var ci = 0; ci < cands.length; ci++) {
