    // 不能只存整段 textContent（那是元素级快照，text 节点上还原不到）。
    svgTexts.push({ nodes: nodes.map(function (x) { return x; }), vals: nodes.map(function (x) { return x.nodeValue; }) });
    nodes[0].nodeValue = out;
