const meta = readFileSync(join(SRC, files[0]), 'utf8');
if (!/==UserScript==/.test(meta)) {
  console.error(`× ${files[0]} 不是用户脚本头（缺少 ==UserScript==）`);
  process.exit(1);
}
const version = (meta.match(/@version\s+(\S+)/) || [])[1];
